module nut(spec, shape, thickness, nutwidth, thread, tolerance, hole_oversize, 
           bevel,bevel1,bevel2,bevang=15,ibevel,ibevel1,ibevel2,blunt_start, blunt_start1, blunt_start2, anchor=BOTTOM, spin=0, orient=UP, oversize=0)
{
   dummyA = assert(is_undef(nutwidth) || (is_num(nutwidth) && nutwidth>0));

   tempspec = _get_spec(spec, "nut_info", "nut", 
                        thread=thread, shape=shape, thickness=thickness);
   spec=_struct_reset(tempspec,[
                                ["width", nutwidth],
                                ["shaft_oversize", hole_oversize],
                               ]);
   dummy=_validate_nut_spec(spec);
   $screw_spec = spec;
   shape = struct_val(spec, "shape");
   pitch =  struct_val(spec, "pitch") ;
   threadspec = pitch==0 ? undef : thread_specification(spec, internal=true, tolerance=tolerance);
   nutwidth = struct_val(spec, "width");
   thickness = struct_val(spec, "thickness");
   threaded_nut(
        nutwidth=nutwidth,
        id=pitch==0 ? _nominal_diam(spec)
          : [mean(struct_val(threadspec, "d_minor")),
             mean(struct_val(threadspec, "d_pitch")),
             mean(struct_val(threadspec, "d_major"))],
        pitch = pitch, 
        h=thickness,
        shape=shape, 
        bevel=bevel,bevel1=bevel1,bevel2=bevel2,bevang=bevang,
        ibevel=ibevel,ibevel1=ibevel1,ibevel2=ibevel2,
        blunt_start=blunt_start, blunt_start1=blunt_start1, blunt_start2=blunt_start2,         
        anchor=anchor,spin=spin,orient=orient) children();
}






// Module: nut_trap_side()
// Synopsis: Creates a side nut trap mask.
// SynTags: Geom
// Topics: Threading, Screws
// See Also: screw(), screw_hole()
// Usage:
//   nut_trap_side(trap_width, [spec], [shape], [thickness], [nutwidth=], [poke_len=], [poke_diam=], [$slop=], [anchor=], [orient=], [spin=]) [ATTACHMENTS];
// Description:
//   Create a nut trap that extends sideways, so the nut slides in perpendicular to the screw axis.
//   The CENTER anchor is the center of the screw hole location in the trap.  The trap width is
//   measured from the screw hole center point.  You can optionally create a poke hole to use for
//   removing the nut by specifying a poke_len value that determines the length of the poke hole, measured
//   from the screw center.  The diameter of the poke hole defaults to the thickness of the nut.  The nut dimensions
//   will be increased by `2*$slop` to allow adjusting the fit of the trap for your printer.  
//   The trap will have a default tag of "remove" if no other tag is in force.  
// Arguments:
//   trap_width = width of nut trap, measured from screw center, must be larger than half the nut width  (If spec is omitted this argument must be given by name.)
//   spec = nut specification, e.g. "M5" or "#8".  See [screw naming](#subsection-screw-naming).  This can also be a screw or nut specification structure of the form produced by {{nut_info()}} or {{screw_info()}}.  
//   shape = "hex" or "square" to specify the shape of the nut.   Default: "hex"
//   thickness = "thin", "normal", or "thick".  "DIN" or "undersized" for metric nuts.  See [nuts](#subsection-nuts). Default: "normal"
//   ---
//   nutwidth = width of the nut.  Default: determined from tables
//   poke_len = length of poke hole.  Default: no poke hole
//   poke_diam = diameter of poke hole.  Default: nut thickness
//   $slop = extra space left to account for printing over-extrusion.  Default: 0
//   anchor = Translate so anchor point is at origin (0,0,0).  See [anchor](attachments.scad#subsection-anchor).  Default: `BOTTOM`
//   spin = Rotate this many degrees around the Z axis after anchor.  See [spin](attachments.scad#subsection-spin).  Default: `0`
//   orient = Vector to rotate top towards, after spin.  See [orient](attachments.scad#subsection-orient).  Default: `UP`
// Side Effects:
//   `$screw_spec` is set to the spec specification structure. 
// Example: Basic trap.  Note that screw center is at the origin and the width is measured from the origin.  
//   nut_trap_side(10, "#8");
// Example: Trap with poke hole for removing nut.  The poke hole length is also measured from the screw center at the origin
//   $fn=16;
//   nut_trap_side(10, "#8", poke_len=10);
// Example: Trap for square nut
//   $fn=16;
//   nut_trap_side(10, "#8", shape="square", poke_len=10);
// Example: Trap with looser fit
//   nut_trap_side(10, "#8", $slop=0.1);
// Example: Trap placed at the bottom of a screw hole
//   $fn=24;
//   screw_hole("#8,1") 
//     position(BOT) nut_trap_side(10,poke_len=8);
// Example: Trap placed at the bottom of a screw hole 2mm extra screw hole below the trap
//   $fn=24;
//   screw_hole("#8,1") 
//     up(2) position(BOT) nut_trap_side(trap_width=10,poke_len=8);
// Example: Hole-trap assembly removed from an object
//   $fn=24;
//   back_half()
//   diff()
//   cuboid(30)
//      position(TOP)screw_hole("#8,1",anchor=TOP) 
//        position(BOT) nut_trap_side(trap_width=16);
// Example: Hole-trap assembly where we position the trap relative to a feature on the model and then position the screw hole through the trap as a child to the trap.  
//  diff()
//   cuboid([30,30,20])
//     position(RIGHT)cuboid([4,20,3],anchor=LEFT)
//       right(1)position(TOP+LEFT)nut_trap_side(15, "#8",anchor=BOT+RIGHT)
//         screw_hole(length=20,anchor=BOT);

module nut_trap_inline(length, spec, shape, l, height, h, nutwidth, anchor=TOP, orient, spin) {
  tempspec = _get_spec(spec, "nut_info", "nut_trap", shape=shape, thickness=undef);
  nutdata = _struct_reset(tempspec, [["width", nutwidth]]);
  $screw_spec = is_def(spec) ? nutdata : $screw_spec;
  dummy = _validate_nut_spec(nutdata);
  length = one_defined([l,length,h,height],"l,length,h,height");
  assert(is_num(length) && length>0, "length must be a positive number");
  nutshape = struct_val(nutdata,"shape");
  nutwidth = struct_val(nutdata,"width")+2*get_slop();
  default_tag("remove"){
    if (nutshape=="square")
      cuboid([nutwidth,nutwidth,length], anchor=anchor, orient=orient, spin=spin) children();
    else
      linear_sweep(hexagon(id=nutwidth),height=length, anchor=anchor,orient=orient, spin=spin) children();
  }
}



// Section: Screw and Nut Information


// Function: screw_info()
// Synopsis: Returns the dimensions and other info for the given screw.
// Topics: Threading, Screws
// See Also: screw(), screw_hole()
// Usage:
//   info = screw_info(name, [head], [drive], [thread=], [drive_size=], [shaft_oversize=], [head_oversize=]);
// Description:
//   Look up screw characteristics for the specified screw type.
//   See [screw and nut parameters](#section-screw-and-nut-parameters) for details on the parameters that define a screw.
//   .
//   The `shaft_oversize` and `head_oversize` parameters specify increases to the shaft and head
//   diameters, respectively. They do not affect length, thread pitch, or head height.
//   .
//   Note that flat head screws are defined by two different diameters, the theoretical maximum diameter, "head_size_sharp"
//   and the actual diameter, "head_size".  The screw form is defined using the theoretical maximum, which gives
//   sharp circular edge at the top of the screw.  Real screws have a flat chamfer around the edge.  
// Figure(2D,Med,NoAxes,VPD=39,VPT=[0,-4,0],VPR=[0,0,0]):  Flat head screw geometry
//   polysharp = [[0, -5.07407], [4.92593, -5.07407], [10, 0], [10, 0.01], [0, 0.01]];
//   color("blue"){
//       xflip_copy()polygon(polysharp);
//       back(1/2)stroke([[-10,0],[10,0]],endcaps="arrow2",width=.15);    
//       back(1.7)text("\"head_size_sharp\"", size=.75,anchor=BACK);
//   }
//   poly= [[0, -5.07407], [4.92593, -5.07407], [9.02, -0.98], [9.02, 0.01], [0, 0.01]];
//   xflip_copy()polygon(poly);
//   rect([10,10],anchor=TOP);
//   color("black"){
//     fwd(1/2)stroke([[-9.02,0],[9.02,0]],endcaps="arrow2",width=.15);
//     fwd(1)text("\"head_size\"", size=.75,anchor=BACK);
//   }  
// Continues:
//   The output is a [struct](structs.scad). Head and drive fields depend on the selected geometry;
//   fields marked optional are present only when supplied or added by a creating module.
//   . 
//   Field              | What it is
//   ------------------ | ---------------
//   "type"           | Always set to "screw_info"
//   "system"         | Either `"UTS"` or `"ISO"` (used for correct tolerance computation).
//   "origin"         | Creating module (optional; absent from direct calls).
//   "name"           | Screw name used to make the structure
//   "diameter"       | The nominal diameter of the screw shaft in mm.
//   "pitch"          | The thread pitch in mm.  (0 for no threads)
//   "head"           | The type of head (a string)
//   "head_size"      | Head diameter, or flat-to-flat width for a hex head, in mm.  Absent for headless screws.
//   "head_size_sharp"| Theoretical sharp head diameter in mm (flat heads only).
//   "head_angle"     | Included countersink angle (flat heads only).
//   "head_height"    | For non-flat heads: Head height beyond the nominal screw length (in mm). For flat heads, optional ovveride to the natural geometry used to produced undercut or custom heads.   
//   "drive"          | The drive type (`"phillips"`, `"torx"`, `"slot"`, `"hex"`, `"none"`)
//   "drive_size"     | Drive number (Phillips or Torx) or recess width in mm (hex or slot); present when a size is known or supplied.
//   "drive_depth"    | Drive recess depth in mm, when supplied by the selected drive data.
//   "length"         | Optional nominal length in mm: total length for flat heads, otherwise from the head underside to the screw tip.
//   "thread_len"     | Optional threaded-section length in mm, added when specified to a creating module.
//   "shaft_oversize"| Optional shaft-diameter increase in mm; zero when absent.
//   "head_oversize"   | Optional head-diameter increase in mm; zero when absent.
//   .
//   If you want to define a custom drive for a screw you will need to provide the drive size and drive depth.  
//
// Arguments:
//   name = screw specification, e.g. "M5x1" or "#8-32".  See [screw naming](#subsection-screw-naming).
//   head = head type.  See [screw heads](#subsection-screw-heads)  Default: none
//   drive = drive type.  See [screw heads](#subsection-screw-heads) Default: none
//   ---
//   thread = thread type or specification. See [screw pitch](#subsection-standard-screw-pitch). Default: "coarse"
//   drive_size = drive number for Phillips or Torx, or recess width in millimeters for hex or slot drives. Specify inch-sized recesses explicitly: `1/8*INCH`.
//   shaft_oversize = amount to increase screw diameter for clearance holes.  Default: 0
//   head_oversize = amount to increase head diameter for countersink holes.  Default: 0

module nut_trap_side(trap_width, spec, shape, thickness, nutwidth, anchor=BOT, orient, spin, poke_len=0, poke_diam) {
  dummy9=assert(is_num(trap_width), "trap_width is missing or the wrong type");
  tempspec = _get_spec(spec, "nut_info", "nut_trap", shape=shape, thickness=thickness);
  nutdata = _struct_reset(tempspec, [["width", nutwidth]]);
  $screw_spec = is_def(spec) ? nutdata : $screw_spec;
  dummy8 = _validate_nut_spec(nutdata);
  nutshape = struct_val(nutdata,"shape");
  nutwidth = struct_val(nutdata,"width")+2*get_slop();
  dummy = assert(is_num(poke_len) && poke_len>=0, "poke_len must be a nonnegative number")
          assert(is_undef(poke_diam) || (is_num(poke_diam) && poke_diam>0), "poke_diam must be a positive number")
          assert(is_num(trap_width) && trap_width>=nutwidth/2, str("trap_width is smaller than nut width: ",nutwidth));
  nutthickness = struct_val(nutdata, "thickness")+2*get_slop();
  cubesize = [trap_width, nutwidth,nutthickness];
  halfwidth = nutshape=="square" ? nutwidth/2 : nutwidth/sqrt(3);
  shift = cubesize[0]/2 - halfwidth/2;
  default_tag("remove")
    attachable(size=cubesize+[halfwidth,0,0], offset=[shift,0,0],anchor=anchor,orient=orient,spin=spin)
    {
       union(){
         if (nutshape=="square") left(nutwidth/2) cuboid(cubesize+[halfwidth,0,0],anchor=LEFT);
         else {
            cuboid(cubesize,anchor=LEFT);
            linear_extrude(height=nutthickness,center=true)hexagon(id=nutwidth);
         }
         if (poke_len>0)
           xcyl(l=poke_len, d=default(poke_diam, nutthickness), anchor=RIGHT);
       }
       children();
    }     
}

// Module: nut_trap_inline()
// Synopsis: Creates an inline nut trap mask.
// SynTags: Geom
// Topics: Threading, Screws
// See Also: screw(), screw_hole()
// Usage:
//   nut_trap_inline(length|l|height|h, [spec], [shape], [$slop=], [anchor=], [orient=], [spin=], [nutwidth=]) [ATTACHMENTS];
// Description:
//   Create a nut trap that extends along the axis of the screw.  The nut width
//   will be increased by `2*$slop` to allow adjusting the fit of the trap for your printer.
//   If no tag is present the trap will be tagged with "remove".  Note that you can omit the specification
//   and it will be inherited from a parent screw_hole to provide the screw size.  It's also possible to 
//   do this backwards, to declare a trap at a screw size and make a child screw hole, which will inherit
//   the screw dimensions.  
// Arguments:
//   length/l/height/h = length/height of nut trap
//   spec = nut specification, e.g. "M5" or "#8".  See [screw naming](#subsection-screw-naming).  This can also be a screw or nut specification structure of the form produced by {{nut_info()}} or {{screw_info()}}.  
//   shape = "hex" or "square to determine type of nut.  Default: "hex"
//   ---
//   nutwidth = width of the nut in millimeters. Default: determined from the specification
//   $slop = extra space left to account for printing over-extrusion.  Default: 0
//   anchor = Translate so anchor point is at origin (0,0,0).  See [anchor](attachments.scad#subsection-anchor).  Default: `TOP`
//   spin = Rotate this many degrees around the Z axis after anchor.  See [spin](attachments.scad#subsection-spin).  Default: `0`
//   orient = Vector to rotate top towards, after spin.  See [orient](attachments.scad#subsection-orient).  Default: `UP`
// Side Effects:
//   `$screw_spec` is set to the spec specification structure. 
// Example: Basic trap
//   nut_trap_inline(10, "#8");
// Example: Basic trap with allowance for a looser fit
//   nut_trap_inline(10, "#8", $slop=.1);
// Example: Square trap (just a cube, but hopefully just the right size)
//   nut_trap_inline(10, "#8", shape="square");
// Example: Attached to a screw hole
//   screw_hole("#8,1",head="socket",counterbore=true, $fn=32) 
//     position(BOT) nut_trap_inline(10);
// Example: Nut trap with child screw hole
//   nut_trap_inline(10, "#8")
//     position(TOP)screw_hole(length=10,anchor=BOT,head="flat",$fn=32);
// Example(Med,NoAxes): a pipe clamp
//   $fa=5;$fs=0.5;
//   bardiam = 32;
//   bandwidth = 10;
//   thickness = 3;
//   back_half()
//   diff()
//     tube(id=bardiam, wall = thickness, h=bandwidth, orient=BACK)
//       left(thickness/2) position(RIGHT) cube([bandwidth, bandwidth, 14], anchor = LEFT, orient=FWD)
//       {
//          screw_hole("#4",length=12, head="socket",counterbore=6,anchor=CENTER)
//             position(BOT) nut_trap_inline(l=6,anchor=BOT);
//          tag("remove")right(1)position(RIGHT)cube([11+thickness, 11, 2], anchor = RIGHT);
//       }

module screw(spec, head, drive, thread, drive_size, 
             length, l, thread_len, tolerance, details=true, 
             undersize, shaft_undersize, head_undersize,
             atype="screw",anchor, spin=0, orient=UP,
             _shoulder_diam=0, _shoulder_len=0,
             bevel,bevel1,bevel2,bevelsize,
             blunt_start,blunt_start1, blunt_start2,
             _internal=false, _counterbore, _teardrop=false)
{
   tempspec = _get_spec(spec, "screw_info", _internal ? "screw_hole" : "screw",
                        thread=thread, head=head, drive=drive, drive_size=drive_size);
   undersize = is_num(undersize) ? [undersize,undersize]
             : undersize;
   dummyA=assert(is_undef(undersize) || is_vector(undersize,2), "Undersize must be a scalar or 2-vector")
          assert(is_undef(undersize) || num_defined([shaft_undersize, head_undersize])==0,
                 "Cannot combine \"undersize\" with other more specific undersize parameters")
          assert(is_bool(_teardrop) ||_teardrop=="max" || all_nonnegative([_teardrop]), str("Invalid teardrop parameter",_teardrop));
   _teardrop = _teardrop==true ? .05 : _teardrop;   // set teardrop default
   shaft_undersize = first_defined([shaft_undersize, undersize[0]]);
   head_undersize = first_defined([head_undersize, undersize[1]]);
   dummyB=assert(is_undef(shaft_undersize) || is_finite(shaft_undersize), "shaft_undersize must be a number")
          assert(is_undef(head_undersize) || is_finite(head_undersize), "head_undersize must be a number")
          assert(is_undef(_counterbore) || is_bool(_counterbore) || (is_finite(_counterbore) && _counterbore>=0),
                 "Counterbore must be a nonnegative number of boolean");
   l = one_defined([l,length],"l,length",dflt=undef);
   _counterbore = _counterbore==true ? struct_val(tempspec,"head_height") 
                : _counterbore==false ? undef
                : _counterbore;
   head = struct_val(tempspec,"head");
   headless = head=="none";
   flathead = is_def(head) && starts_with(head,"flat");
   reset_headsize = _internal && flathead ? struct_val(tempspec,"head_size_sharp") : undef;
   spec=_struct_reset(tempspec,[
                                ["length", l],
                                ["shaft_oversize", u_mul(-1,shaft_undersize)],
                                ["head_oversize", u_mul(-1,head_undersize)],
                                ["counterbore", _counterbore],
                                ["thread_len", thread_len],
                                ["head_size", reset_headsize],
                               ]);
   dummy = _validate_screw_spec(spec);
   $screw_spec = spec;
   pitch =  struct_val(spec, "pitch") ;
   threadspec = pitch==0 ? undef : thread_specification(spec, internal=_internal, tolerance=tolerance);
   nominal_diam = _nominal_diam(spec);
   d_major = pitch==0 ? nominal_diam : mean(struct_val(threadspec, "d_major"));
   length = struct_val(spec,"length");
   counterbore = default(struct_val(spec,"counterbore"),0);
   user_thread_len = struct_val(spec,"thread_len");
   dummyC = assert(in_list(atype,["shaft","head","shank","threads","screw","shoulder"]),str("Unknown anchor type: \"",atype,"\""))
            assert(is_finite(length) && length>0, "Must specify positive screw length")
            assert(is_finite(_shoulder_len) && _shoulder_len>=0, "Must specify a nonegative shoulder length")
            assert(is_finite(_shoulder_diam) && _shoulder_diam>=0, "Must specify nonnegative shoulder diameter")
            assert(is_undef(user_thread_len) || (is_finite(user_thread_len) && user_thread_len>=0), "Must specify nonnegative thread length");
   sides = max(pitch==0 ? 3 : 12, segs(nominal_diam/2));
   rad_scale = _internal? (1/cos(180/sides)) : 1;
   islop = _internal ? 4*get_slop() : 0;
   head_height = headless || flathead ? 0 
               : counterbore==true || is_undef(counterbore) || counterbore==0 ? struct_val(spec, "head_height")
               : counterbore;
   head_diam = struct_val(spec, "head_size",0) + struct_val(spec, "head_oversize",0);
   flat_height = !flathead ? 0 
               : let( given_height = struct_val(spec, "head_height"))
                 all_positive(given_height) ? given_height
               : (struct_val(spec,"head_size_sharp")+struct_val(spec,"head_oversize",0)-d_major*rad_scale-islop)/2/tan(struct_val(spec,"head_angle")/2);

   flat_cbore_height = flathead && is_num(counterbore) ? counterbore : 0;

   blunt_start1 = first_defined([blunt_start1,blunt_start,true]);
   blunt_start2 = first_defined([blunt_start2,blunt_start,true]);

   shoulder_adj = _shoulder_len>0 ? flat_height:0;  // Adjustment because flathead height doesn't count toward shoulder length
   shoulder_full = _shoulder_len==0 ? 0 : _shoulder_len + flat_height;
   shank_len = is_def(user_thread_len) ? length - user_thread_len - (_shoulder_len==0?flat_height:0) : 0;
   thread_len = is_def(user_thread_len) ? user_thread_len
              : length - (_shoulder_len==0?flat_height:0);
   dummyD = assert(shank_len>=0, "thread_len exceeds the available shaft length")
            assert(!(atype=="shank" && shank_len==0), "Specified atype of \"shank\" but screw has no shank (thread_len not given or it equals shaft length)")
            assert(!(atype=="shoulder" && _shoulder_len==0), "Specified atype of \"shoulder\" but screw has no shoulder")
            assert(!(atype=="threads" && thread_len==0), "Specified atype of \"threads\" but screw has no threaded part (thread_len=0)")
            assert(!(atype=="head" && headless), "You cannot anchor headless screws with atype=\"head\"");
   eps_gen = 0.01;
   eps_shoulder = headless && !_internal ? 0 : eps_gen;
   eps_shank = headless && !_internal && _shoulder_len==0 ? 0 : eps_gen;
   eps_thread = headless && !_internal && shank_len==0 && _shoulder_len==0 ? 0 : eps_gen;
   dummyL = assert(_shoulder_len>0 || is_undef(flat_height) || flat_height < length,
                   str("Length of screw (",length,") is shorter than the flat head height (",flat_height,")"));
   offset = atype=="head" ? (-head_height+flat_height-flat_cbore_height)/2
          : atype=="shoulder" ? _shoulder_len/2 + flat_height
          : atype=="shaft" ? _shoulder_len + (length+flat_height+shoulder_adj)/2
          : atype=="shank" ? _shoulder_len + (length-thread_len+flat_height+shoulder_adj)/2
          : atype=="threads" ? _shoulder_len + shoulder_adj + length-thread_len + thread_len/2
          : atype=="screw" ? (length-head_height+_shoulder_len+shoulder_adj-flat_cbore_height)/2
          : assert(false,"Unknown atype");
   dummyM = //assert(!headless || !in_list(anchor,["head_top","head_bot","head_center"]), str("Anchor \"",anchor,"\" not allowed for headless screw"))
            assert(shank_len>0 || !in_list(anchor,["shank_top","shank_bot","shank_center"]),
                   str("Screw has no unthreaded shank so anchor \"",anchor,"\" is not allowed"));
   anchor_list = [
          named_anchor("top", [0,0,offset+head_height+flat_cbore_height]),
          named_anchor("bot", [0,0,-length-shoulder_full+offset]),
          named_anchor("center", [0,0, -length/2 - shoulder_full/2 + (head_height+flat_cbore_height)/2 + offset]),
          named_anchor("head_top", [0,0,head_height+offset]),
          named_anchor("head_bot", [0,0,-flat_height+offset]),
          named_anchor("head_center", [0,0,(head_height-flat_height)/2+offset]),
          if (_shoulder_len>0) named_anchor("shoulder_top", [0,0,offset-flat_height]),
          if (_shoulder_len>0) named_anchor("shoulder_bot", [0,0,offset-shoulder_full]),
          if (_shoulder_len>0) named_anchor("shoulder_center", [0,0,offset-flat_height-_shoulder_len/2]),
          named_anchor("shaft_top", [0,0,-_shoulder_len-flat_height+offset]),
          named_anchor("shaft_bot", [0,0,-length-shoulder_full+offset]),
          named_anchor("shaft_center", [0,0,(-_shoulder_len-flat_height-length-shoulder_full)/2+offset]),
          if (shank_len>0) named_anchor("shank_top", [0,0,-_shoulder_len-flat_height+offset]),
          if (shank_len>0) named_anchor("shank_bot", [0,0,-shank_len-_shoulder_len-flat_height+offset]),
          if (shank_len>0) named_anchor("shank_center", [0,0,-shank_len/2-_shoulder_len-flat_height+offset]),
          named_anchor("threads_top", [0,0,-shank_len-_shoulder_len-flat_height+offset]),
          named_anchor("threads_bot", [0,0,-length-shoulder_full+offset]),
          named_anchor("threads_center", [0,0,(-shank_len-length-_shoulder_len-shoulder_full-flat_height)/2+offset])
   ];
   vnf = head=="hex" && atype=="head" && counterbore==0 ? linear_sweep(hexagon(id=head_diam*rad_scale),height=head_height,center=true) : undef;
   head_diam_full = head=="hex" ? 2*head_diam/sqrt(3) : head_diam;
   attach_d = in_list(atype,["threads","shank","shaft"]) ? d_major 
            : atype=="screw" ? max(d_major,_shoulder_diam,default(head_diam_full,0))
            : atype=="shoulder" ? _shoulder_diam
            : is_def(vnf) ? undef
            : head_diam_full;
   attach_l = atype=="shaft" ? length-(_shoulder_len>0?0:flat_height)
            : atype=="shoulder" ? _shoulder_len
            : atype=="shank" ? shank_len
            : atype=="threads" ? thread_len
            : atype=="screw" ? length+head_height+shoulder_full + flat_cbore_height
            : is_def(vnf) ? undef
            : head_height+flat_height+flat_cbore_height;
   bevelsize = default(bevelsize, d_major/12);
   bevel1 = first_defined([bevel1,bevel,true]);
   bevel2 = first_defined([bevel2,bevel,headless && _shoulder_len==0 && shank_len==0]);
   attachable(
              vnf = vnf, 
              d = u_add(u_mul(attach_d, rad_scale), islop),
              l = attach_l,
              orient = orient,
              anchor = anchor,
              spin = spin,
              anchors=anchor_list)
   {
     up(offset)
       difference(){
         union(){
           screw_head(spec,details,counterbore=counterbore,flat_height=flat_height,
                      slop=islop,teardrop=_teardrop);
           if (_shoulder_len>0)
             up(eps_shoulder-flat_height){
               if (_teardrop!=false) //////
                 teardrop(d=_shoulder_diam*rad_scale+islop,cap_h=is_num(_teardrop) ? (_shoulder_diam*rad_scale+islop)/2*(1+_teardrop):undef,
                          h=_shoulder_len+eps_shoulder, anchor=FRONT, orient=BACK, $fn=sides);
               else
                 cyl(d=_shoulder_diam*rad_scale+islop, h=_shoulder_len+eps_shoulder, anchor=TOP, $fn=sides, chamfer1=details ? _shoulder_diam/30:0);
             }
           if (shank_len>0 || pitch==0){
             L = pitch==0 ? length - (_shoulder_len==0?flat_height:0) : shank_len;
             bevsize = (_internal ? -1 : 1)*bevelsize;
             bev1 = pitch!=0 ? 0
                  : bevel1==true ? bevsize
                  : bevel1==false ? 0
                  : bevel1=="reverse" ? -bevsize
                  : bevel1;
             bev2 = pitch!=0 ? 0
                  : bevel2==true ? bevsize
                  : bevel2==false ? 0
                  : bevel2=="reverse" ? -bevsize
                  : bevel2;
             down(_shoulder_len+flat_height-eps_shank)
               if (_teardrop!=false)  ///////
                 teardrop(d=d_major*rad_scale+islop, cap_h=is_num(_teardrop) ? (d_major*rad_scale+islop)/2*(1+_teardrop) : undef,
                          h=L+eps_shank, anchor=FRONT, orient=BACK, $fn=sides, chamfer1=bev1, chamfer2=bev2);
               else
                 cyl(d=d_major*rad_scale+islop, h=L+eps_shank, anchor=TOP, $fn=sides, chamfer1=bev1, chamfer2=bev2);
           }
           if (thread_len>0 && pitch>0){
             down(_shoulder_len+flat_height+shank_len-eps_thread)
                   threaded_rod([mean(struct_val(threadspec, "d_minor")),
                                 mean(struct_val(threadspec, "d_pitch")),
                                 d_major], 
                      pitch = struct_val(threadspec, "pitch"),
                      l=thread_len+eps_thread, left_handed=false, internal=_internal, 
                      bevel1=bevel1,
                      bevel2=bevel2,teardrop=_teardrop,
                      blunt_start=blunt_start, blunt_start1=blunt_start1, blunt_start2=blunt_start2, 
                      $fn=sides, anchor=TOP);
            }

         }
         if (!_internal) _driver(spec);
       }
     children();
   }  
}



// Module: screw_hole()
// Synopsis: Creates a screw hole.
// SynTags: Geom
// Topics: Threading, Screws
// See Also: screw()
// Usage:
//   screw_hole([spec], [head], [thread=], [length=|l=], [oversize=], [hole_oversize=], [teardrop=], [head_oversize=], [tolerance=], [$slop=], [blunt_start=], [anchor=], [atype=], [orient=], [spin=], [counterbore=]) [ATTACHMENTS];
// Description:
//   Create a screw hole mask.  See [screw and nut parameters](#section-screw-and-nut-parameters) for details on the parameters that define a screw.
//   The screw hole can be threaded to receive a screw or it can be an unthreaded clearance hole.  
//   The tolerance determines the dimensions of the screw
//   based on ISO and ASME standards.  Screws fabricated at those dimensions will mate properly with standard hardware.
//   The $slop argument makes the hole larger by 4*$slop to account for printing overextrusion.  It defaults to 0.
//   .
//   You can generate a screw specification from {{screw_info()}}, possibly create a modified version, and pass that in rather than giving the parameters.
//   .
//   The tolerance should be a nut tolerance for a threaded hole or a clearance hole tolerance for clearance holes.
//   For clearance holes, the UTS tolerances are "normal", "loose" and "close".  ASME also specifies the same naming for metric clearance holes.
//   However, ISO gives "fine", "medium" and "coarse" instead.  This function accepts all of these in either system.  It also takes "tight" to be equivalent to "close",
//   even though no standard suggests it, because it's a natural opposite of "loose".  The official tolerance designations for ISO are "H12" for "fine", "H13" for "medium"
//   and "H14" for "coarse".  These designations will also work, but only for metric holes.  You can also set tolerance to 0 or "none" to produce holes at the nominal size.
//   .
//   If you want to produce holes for tapping you can use a tolerance of "tap".  This produces a hole of the nominal screw diameter reduced by the thread pitch.  You may still
//   need to adjust $slop for best results.  Some people screw machine screws directly into plastic without tapping.  This works better with a somewhat larger hole, so
//   a tolerance of "self tap" produces such a hole.  Note that this tolerance also makes the default bevel2=true to bevel the top, which makes it much easier
//   to start the screw.  The "self tap" tolerance subtracts `0.72 * pitch` when pitch is below 1mm, `0.6 * pitch` when the pitch is over 1.5mm, and it interpolates between.
//   It was tested in PLA with a Prusa MK3S and $slop=0.05 and worked on UTS screws from #2 up to 1/2 inch.  
//   .
//   The counterbore parameter adds a cylindrical clearance hole above the screw shaft.  For flat heads it extends above the flathead and for other screw types it 
//   replaces the head with a cylinder large enough in diameter for the head to fit.  For a flat head you must specify the length of the counterbore.  For other heads you can
//   set counterbore to true and it will be sized to match the head height.  The counterbore will extend 0.01 above the TOP of the hole mask to ensure no
//   problems with differences.  Note that the counterbore defaults to true for non-flathead screws.  If you want the actual head shape to appear, set counterbore to zero.
//   .
//   For 3d printing circular holes can be problematic.  One solution is to use octagonal holes, setting $fn=8.  Another option is to use a teardrop hole, which
//   can be accomplished by setting `teardrop=true`.  The point of the teardrop will point in the Y direction (BACK) so you will need to ensure that you orient it
//   correctly in your final model.  
//   .
//   Anchoring follows {{screw()}}. The "screw" anchor type and named "top", "bot", and "center" anchors
//   describe the entire hole mask, including the counterbore. The "head" anchor type includes the
//   counterbore, but for flat heads the named "head_top", "head_bot", and "head_center" anchors describe
//   only the countersunk head recess below it. For other heads, these named anchors describe the
//   counterbore that replaces the head recess. Teardrop extensions are ignored for anchoring.
//   .
//   All named anchors point in the native +Z direction. Shank and thread anchors follow the 
//   division specified by `thread_len`, even for an unthreaded hole. Shank anchors are unavailable when
//   the shank length is zero. With `thread_len=0`, all thread anchors coincide at the shaft bottom.
//   For headless holes, all head anchors coincide at the shaft top.
// Arguments:
//   spec = screw specification, e.g. "M5x1" or "#8-32".  See [screw naming](#subsection-screw-naming).  This can also be a screw specification structure of the form produced by {{screw_info()}}.  
//   head = head type.  See [screw heads](#subsection-screw-heads)  Default: none
//   ---
//   thread = thread type or specification for threaded masks, true to make a threaded mask with the standard threads, or false to make an unthreaded mask.  See [screw pitch](#subsection-standard-screw-pitch). Default: false
//   teardrop = If true, adds a teardrop profile to the hole for 3d printability of horizontal holes. If numeric, specifies the proportional extra distance of the teardrop flat top from the screw center, or set to "max" for a pointed teardrop. Default: false
//   oversize = amount to increase diameter of the screw hole (hole and countersink).  A scalar or length 2 vector.  Default: use computed tolerance
//   hole_oversize = amount to increase diameter of the hole.  Overrides the use of tolerance and replaces any settings given in the screw specification. 
//   head_oversize = amount to increase diameter of head.  Overrides the user of tolerance and replaces any settings given in the screw specification.  
//   length / l= length of screw (in mm)
//   counterbore = set to length of counterbore, or true to make a counterbore equal to head height.  Default: false for flat heads and headless, true otherwise
//   tolerance = threading or clearance hole tolerance.  For internal threads, detrmines actual thread geometry based on nominal sizing.  See [tolerance](#subsection-tolerance). Default is "2B" for UTS and 6H for ISO.  For clearance holes, determines how much clearance to add.  Default is "normal".  
//   bevel = if true create bevel at both ends of hole.  Default: see below
//   bevel1 = if true create bevel at bottom end of hole.  Default: false
//   bevel2 = if true create bevel at top end of hole.     Default: true when tolerance="self tap", false otherwise
//   blunt_start = if true and hole is threaded, create blunt start threads.  Default: true
//   blunt_start1 = if true and hole is threaded, create blunt start threads at bottom end.
//   blunt_start2 = if true and hole is threaded, create blunt start threads top end.
//   $slop = add extra gap to account for printer overextrusion.  Default: 0
//   atype = anchor type, one of "screw", "head", "shaft", "threads", "shank"
//   anchor = Translate so anchor point on the shaft is at origin (0,0,0).  See [anchor](attachments.scad#subsection-anchor).  Default: `CENTER`
//   spin = Rotate this many degrees around the Z axis after anchor.  See [spin](attachments.scad#subsection-spin).  Default: `0`
//   orient = Vector to rotate top towards, after spin.  See [orient](attachments.scad#subsection-orient).  Default: `UP`
// Side Effects:
//   `$screw_spec` is set to the spec specification structure. 
// Anchor Types:
//   screw =

module screw_head(screw_info,details=false, counterbore=0,flat_height,teardrop=false,slop=0) {
   no_children($children);
   head_oversize = struct_val(screw_info, "head_oversize",0) + slop;
   head = struct_val(screw_info, "head");
   head_size = struct_val(screw_info, "head_size",0) + head_oversize;
   head_height = struct_val(screw_info, "head_height");
   dum0=assert(is_def(head_height) || in_list(head,["flat","none"]), "Undefined head height only allowed with flat head or headless screws")
        assert(is_bool(teardrop) || teardrop=="max" || all_nonnegative([teardrop]),"Teardrop parameter invalid");
   teardrop = teardrop==true ? .05 : teardrop;
   heightok = (is_undef(head_height) && in_list(head,["flat","none"])) || all_positive(head_height);
   dum1=assert(heightok, "Head hight must be a postive number");
   dum2=assert(counterbore==0 || counterbore==false || head!="none", "Cannot counterbore a headless screw");
   counterbore_temp = counterbore==false? 0 
                    : head!="flat" && counterbore==true ? head_height 
                    : counterbore;
   dum3=assert(is_finite(counterbore_temp) && counterbore_temp>=0, str(counterbore==true? "Must specify numerical counterbore height with flat head screw"
                                                             : "Counterbore must be a nonnegative number"));

   counterbore = counterbore_temp==0 && head!="flat" ? counterbore_temp : counterbore_temp + 0.01;
   adj_diam = struct_val(screw_info, "diameter") + head_oversize;   // Used for determining chamfers and ribbing
   attachable(){
     union(){
         if (head!="flat" && counterbore>0){
           d = head=="hex"? 2*head_size/sqrt(3) : head_size;
           if (teardrop!=false)
             teardrop(d=d, l=counterbore, cap_h=is_num(teardrop) ? d/2*(1+teardrop):undef, orient=BACK, anchor=BACK);
           else                    
             cyl(d=d, l=counterbore, anchor=BOTTOM);
         }  
         if (head=="flat") {   // For flat head, counterbore is integrated
           dummy = assert(all_positive([flat_height]), "flat_height must be given for flat heads");
           angle = struct_val(screw_info, "head_angle")/2;
           sharpsize = struct_val(screw_info, "head_size_sharp")+head_oversize;
           sidewall_height = (sharpsize - head_size)/2 / tan(angle);
           cylheight = counterbore + sidewall_height;
           slopeheight = flat_height - sidewall_height;
           r1 = head_size/2;
           r2 = r1 - tan(angle)*slopeheight;
           n = segs(r1);
           prof1 = teardrop!=false ? teardrop2d(r=r1,cap_h=is_num(teardrop)?r1*(1+teardrop):undef,$fn=n) : circle(r=r1, $fn=n);
           prof2 = teardrop!=false ? teardrop2d(r=r2,cap_h=is_num(teardrop)?r2*(1+teardrop):undef,$fn=n) : circle(r=r2, $fn=n);
           skin([prof2,prof1,prof1], z=[-flat_height, -flat_height+slopeheight, counterbore],slices=0);
         }
         if (head!="flat" && counterbore==0) {
           if (in_list(head,["round","pan round","button","fillister","cheese"])) {
             base = head=="fillister" ? 0.75*head_height :
                    head=="pan round" ? .6 * head_height :
                    head=="cheese" ? .7 * head_height :
                    0.1 * head_height;   // round and button
             head_size2 = head=="cheese" ?  head_size-2*tan(5)*head_height : head_size; // 5 deg slope on cheese head
             segs = segs(head_size);
             cyl(l=base, d1=head_size, d2=head_size2,anchor=BOTTOM, $fn=segs)
               attach(TOP)
                 zrot(180) // Needed to align facets when $fn is odd
                 rotate_extrude($fn=segs)  // ensure same number of segments for cap as for head body
                   intersection(){
                     arc(points=[[-head_size2/2,0], [0,-base+head_height * (head=="button"?4/3:1)], [head_size2/2,0]]);
                     square([head_size2, head_height-base]);
                   }
           }
           if (head=="pan flat")
             cyl(l=head_height, d=head_size, rounding2=0.2*head_size, anchor=BOTTOM);
           if (head=="socket")
             cyl(l=head_height, d=head_size, anchor=BOTTOM, chamfer2=details? adj_diam/10:undef);
           if (head=="socket ribbed"){
             // These numbers are based on ISO specifications that dictate how much oversizsed a ribbed socket head can be
             // We are making our ribbed heads the same size as unribbed (by cutting the ribbing away), but these numbers are presumably a good guide
             rib_size = [[2, .09],
                         [3, .09],
                         [6, .11],
                         [12, .135],
                         [20, .165]];
             intersection() {
               cyl(h=head_height/4, d=head_size, anchor=BOT)
                  attach(TOP) cyl(l=head_height*3/4, d=head_size, anchor=BOT, texture="trunc_ribs", tex_reps=[31,1],
                                  tex_inset=true, tex_depth=-lookup(adj_diam,rib_size));
               cyl(h=head_height,d=head_size, chamfer2=adj_diam/10, anchor=BOT);
             }
           }
           if (head=="hex")
             up(head_height/2)_nutshape(head_size,head_height,"hex",false,true);
         }
     }    
     union(){};
   }
}


// Section: Nuts and nut traps


// Module: nut()
// Synopsis: Creates a standard nut.
// SynTags: Geom
// Topics: Threading, Screws
// See Also: screw(), screw_hole()
// Usage:
//   nut([spec], [shape], [thickness], [nutwidth=], [thread=], [tolerance=], [hole_oversize=], [bevel=], [$slop=], [anchor=], [spin=], [orient=]) [ATTACHMENTS];
// Description:
//   Generates a hexagonal or square nut.  See [screw and nut parameters](#section-screw-and-nut-parameters) for details on the parameters that define a nut.
//   As with screws, you can give the specification in `spec` and then omit the name.  The diameter is the flat-to-flat
//   size of the nut produced.  The thickness can be "thin", "normal" or "thick" to choose standard nut dimensions.  For metric
//   nuts you can also use thickness values of "DIN" or "undersized".  The nut's shape is hexagonal by default; set shape to "square" for
//   a square nut.
//   .
//   By default all nuts have the internal holes beveled and hex nuts have their corners beveled.  Square nuts get no outside bevel by default.
//   ASME specifies that small square nuts should not be beveled, and many square nuts are beveled only on one side.   The bevel angle, specified with bevang,
//   gives the angle for the bevel.  The default of 15 is shallow and may not be printable.  Internal bevels are sized from the thread depth and limited by nut thickness and wall. See {{generic_threaded_nut()}}.  
//   .
//   The tolerance determines the actual thread sizing based on the nominal size in accordance with standards.  
//   The $slop parameter determines extra gaps left to account for printing overextrusion.  It defaults to 0.
// Arguments:
//   spec = nut specification, e.g. "M5x1" or "#8-32".  See [screw naming](#subsection-screw-naming).  This can also be a nut or screw specification structure of the form produced by {{nut_info()}} or {{screw_info()}}.  
//   shape = "hex" or "square" to specify nut shape.  Default: "hex"
//   thickness = "thin", "normal", "thick", or a thickness in mm.  See [nuts](#subsection-nuts).  Default: "normal"
//   ---
//   nutwidth = width of nut (overrides table values)
//   thread = thread type or specification. See [screw pitch](#subsection-standard-screw-pitch). Default: "coarse"
//   hole_oversize = amount to increase hole diameter.  Default: 0
//   bevel = Outside nut bevel: true for automatic size, a nonnegative number for radial inset in mm, or false for no bevel. See {{generic_threaded_nut()}}. Default: true for hex nuts, false for square nuts
//   bevel1 = Bottom outside bevel; accepts the same values as bevel and overrides it.
//   bevel2 = Top outside bevel; accepts the same values as bevel and overrides it.
//   bevang = set the angle for the outside nut bevel.  Default: 15
//   ibevel = Inside bevel: true for automatic size, a number for size in mm, false for none, or "reverse" for an inverted automatic bevel. See {{generic_threaded_nut()}}. Default: true
//   ibevel1 = Bottom inside bevel; accepts the same values as ibevel and overrides it.
//   ibevel2 = Top inside bevel; accepts the same values as ibevel and overrides it.
//   blunt_start = If true apply truncated blunt start threads at both ends.  Default: true
//   blunt_start1 = If true apply truncated blunt start threads bottom end.
//   blunt_start2 = If true apply truncated blunt start threads top end.
//   tolerance = nut tolerance.  Determines actual nut thread geometry based on nominal sizing.  See [tolerance](#subsection-tolerance). Default is "2B" for UTS and "6H" for ISO.
//   $slop = extra space left to account for printing over-extrusion.  Default: 0
//   anchor = Translate so anchor point is at origin (0,0,0).  See [anchor](attachments.scad#subsection-anchor).  Default: `BOTTOM`
//   spin = Rotate this many degrees around the Z axis after anchor.  See [spin](attachments.scad#subsection-spin).  Default: `0`
//   orient = Vector to rotate top towards, after spin.  See [orient](attachments.scad#subsection-orient).  Default: `UP`
// Side Effects:
//   `$screw_spec` is set to the spec specification structure. 
// Example: All the UTS nuts at one size.  Note that square nuts come in only one thickness.  
//   xdistribute(spacing=0.75*INCH){
//       nut("3/8",thickness="thin");
//       nut("3/8",thickness="normal");
//       nut("3/8",thickness="thick");
//       nut("3/8",shape="square");
//   }
// Example: All the ISO (and DIN) nuts at one size.  Note that M10 is one of the four cases where the DIN nut width is larger.  
//   ydistribute(spacing=30){
//      xdistribute(spacing=22){
//         nut("M10", thickness="thin");
//         nut("M10",thickness="undersized");
//         nut("M10",thickness="normal");
//         nut("M10",thickness="thick");
//      }
//      xdistribute(spacing=25){
//         nut("M10", shape="square", thickness="thin");
//         nut("M10", shape="square", thickness="normal");      
//      }
//   }
// Example: The three different UTS nut tolerances (thickner than normal nuts)
//   module mark(number)
//   {
//     difference(){
//        children();
//        ycopies(n=number, spacing=1.5)right(.25*INCH-2)up(8-.35)cyl(d=1, h=1);
//     }
//   }
//   $fn=64;
//   xdistribute(spacing=17){
//     mark(1) nut("1/4-20", thickness=8, nutwidth=0.5*INCH,tolerance="1B");
//     mark(2) nut("1/4-20", thickness=8, nutwidth=0.5*INCH,tolerance="2B");
//     mark(3) nut("1/4-20", thickness=8, nutwidth=0.5*INCH,tolerance="3B");
//   }
// Example: Threadless nut
//   nut("#8", thread="none");

module metric_bolt(
    headtype="socket",
    size=3,
    l=12,
    shank=0,
    pitch=undef,
    details=false,
    coarse=true,
    phillips=undef,
    torx=undef,
    flange=0,
    anchor="base",
    spin=0,
    orient=UP
) {
    D = headtype != "hex"?
        get_metric_socket_cap_diam(size) :
        get_metric_bolt_head_size(size);
    H = headtype == "socket"?
        get_metric_socket_cap_height(size) :
        get_metric_bolt_head_height(size);
    P = coarse?
        (pitch==undef? get_metric_iso_coarse_thread_pitch(size) : pitch) :
        (pitch==undef? get_metric_iso_fine_thread_pitch(size) : pitch);
    tlen = l - min(l, shank);
    sides = max(12, segs(size/2));
    tcirc = D/cos(30);
    bevtop = (tcirc-D)/2;
    bevbot = P/2;

    headlen = (
        (headtype == "pan" || headtype == "round" || headtype == "button")? H*0.75 :
        (headtype == "countersunk")? (D-size)/2 :
        (headtype == "oval")? ((D-size)/2 + D/2/3) :
        H
    );
    base = l/2 - headlen/2;
    sunklen = (
        (headtype == "oval")? (D-size)/2 :
        headlen-0.001
    );

    anchors = [
        named_anchor("countersunk", [0,0,base+sunklen]),
        named_anchor("base",   [0,0,base]),
        named_anchor("shank",  [0,0,base-shank])
    ];

    //color("silver")
    attachable(anchor,spin,orient, d=size, l=headlen+l, anchors=anchors) {
        up(base) {
            difference() {
                union() {
                    // Head
                    if (headtype == "hex") {
                        difference() {
                            cylinder(d=tcirc, h=H, $fn=6);

                            // Bevel hex nut top
                            if (details) {
                                up(H-bevtop) {
                                    difference() {
                                        cube([tcirc+1, tcirc+1, bevtop+0.5], anchor=BOTTOM);
                                        down(0.01) cylinder(d1=tcirc, d2=tcirc-bevtop*2, h=bevtop+0.02, center=false);
                                    }
                                }
                            }
                        }
                    } else if (headtype == "socket") {
                        sockw = get_metric_socket_cap_socket_size(size);
                        sockd = get_metric_socket_cap_socket_depth(size);
                        difference() {
                            cylinder(d=D, h=H);
                            up(H-sockd) cylinder(h=sockd+0.1, d=sockw/cos(30), $fn=6);
                            if (details) {
                                kcnt = 36;
                                zrot_copies(n=kcnt, r=D/2) up(H/3) cube([PI*D/kcnt/2, PI*D/kcnt/2, H], anchor=BOTTOM);
                            }
                        }
                    } else if (headtype == "pan") {
                        cyl(l=H*0.75, d=D, rounding2=H*0.75/2, anchor=DOWN);
                    } else if (headtype == "round") {
                        top_half(D) zscale(H*0.75/D*2) sphere(d=D);
                    } else if (headtype == "button") {
                        up(H*0.75/3) top_half(D) zscale(H*0.75*2/3/D*2) sphere(d=D);
                        cylinder(d=D, h=H*0.75/3+0.01, center=false);
                    } else if (headtype == "countersunk") {
                        cylinder(h=(D-size)/2, d1=size, d2=D);
                    } else if (headtype == "oval") {
                        up((D-size)/2) top_half(D) zscale(0.333) sphere(d=D);
                        cylinder(h=(D-size)/2, d1=size, d2=D);
                    }

                    // Flange
                    if (flange>0) {
                        up(headtype == "countersunk" || headtype == "oval"? (D-size)/2 : 0) {
                            cylinder(d=D+flange, h=H/8, center=false);
                            up(H/8) cylinder(d1=D+flange, d2=D, h=H/8, center=false);
                        }
                    }

                    // Unthreaded Shank
                    if (tlen < l) {
                        down(l-tlen) cylinder(d=size, h=l-tlen+0.05, center=false, $fn=sides);
                    }

                    // Threads
                    down(l) {
                        difference() {
                            up(tlen/2+0.05) {
                                if (tlen > 0) {
                                    if (P > 0) {
                                        threaded_rod(d=size, l=tlen+0.05, pitch=P, $fn=sides);
                                    } else {
                                        cylinder(d=size, h=tlen+0.05, $fn=sides, center=true);
                                    }
                                }
                            }

                            // Bevel bottom end of threads
                            if (details) {
                                difference() {
                                    down(0.5) cube([size+1, size+1, bevbot+0.5], anchor=BOTTOM);
                                    cylinder(d1=size-bevbot*2, d2=size, h=bevbot+0.01, center=false);
                                }
                            }
                        }
                    }
                }

                // Phillips drive hole
                if (headtype != "socket" && phillips != undef) {
                    down(headtype != "hex"? H/6 : 0) {
                        phillips_mask(size=phillips); //, shaft=D);
                    }
                }

                // Torx drive hole
                if (headtype != "socket" && torx != undef) {
                    up(1) torx_mask(size=torx, l=H+0.1, center=false);
                }
            }
        }
        children();
    }
}


// Module: metric_nut()
// Synopsis: Creates a standard metric nut model.
// Description:
//   Makes a model of a standard nut for a standard metric screw.
// Arguments:
//   size = standard metric screw size in mm. (Default: 3)
//   hole = include the hole in the nut.  (Default: true)
//   pitch = pitch of threads in the hole.  No threads if not given.
//   flange = radius of flange beyond the head.  Default = 0 (no flange)
//   details = true if model should be rendered with extra details.  (Default: false)
//   anchor = Translate so anchor point is at origin (0,0,0).  See [anchor](attachments.scad#subsection-anchor).  Default: `CENTER`
//   spin = Rotate this many degrees around the Z axis after anchor.  See [spin](attachments.scad#subsection-spin).  Default: `0`
//   orient = Vector to rotate top towards, after spin.  See [orient](attachments.scad#subsection-orient).  Default: `UP`
//   center = If true, centers the nut at the origin.  If false, sits on top of XY plane.  Overrides `anchor` if given.
// Example: No details, No Hole.  Useful for a mask.
//   metric_nut(size=10, hole=false);
// Example:  Hole, with No Threads
//   metric_nut(size=10, hole=true);
// Example:  Threads
//   metric_nut(size=10, hole=true, pitch=1.5);
// Example:  Details
//   metric_nut(size=10, hole=true, pitch=1.5, details=true);
// Example:  Centered
//   metric_nut(size=10, hole=true, pitch=1.5, details=true, center=true);
// Example:  Flange
//   metric_nut(size=10, hole=true, pitch=1.5, flange=3, details=true);

module metric_nut(
    size=3,
    hole=true,
    pitch=undef,
    details=false,
    flange=0,
    center,
    anchor,
    spin=0,
    orient=UP
) {
    H = get_metric_nut_thickness(size);
    D = get_metric_nut_size(size);
    boltfn = max(12, segs(size/2));
    nutfn = max(12, segs(D/2));
    dcirc = D/cos(30);
    bevtop = (dcirc - D)/2;

    //color("silver")
    anchor = get_anchor(anchor,center,BOT,CENTER);
    attachable(anchor,spin,orient, d=dcirc+flange, l=H) {
        difference() {
            union() {
                difference() {
                    cylinder(d=dcirc, h=H, center=true, $fn=6);
                    if (details) {
                        up(H/2-bevtop) {
                            difference() {
                                cube([dcirc+1, dcirc+1, bevtop+0.5], anchor=BOTTOM);
                                down(0.01) cylinder(d1=dcirc, d2=dcirc-bevtop*2, h=bevtop+0.02, center=false, $fn=nutfn);
                            }
                        }
                        if (flange == 0) {
                            down(H/2) {
                                difference() {
                                    down(0.5) cube([dcirc+1, dcirc+1, bevtop+0.5], anchor=BOTTOM);
                                    down(0.01) cylinder(d1=dcirc-bevtop*2, d2=dcirc, h=bevtop+0.02, center=false, $fn=nutfn);
                                }
                            }
                        }
                    }
                }
                if (flange>0) {
                    down(H/2) {
                        cylinder(d=D+flange, h=H/8, center=false);
                        up(H/8) cylinder(d1=D+flange, d2=D, h=H/8, center=false);
                    }
                }
            }
            if (hole == true) {
                if (pitch == undef) {
                    cylinder(r=size/2, h=H+0.5, center=true, $fn=boltfn);
                } else {
                    threaded_rod(d=size, l=H+0.5, pitch=pitch, $fn=boltfn);
                }
            }
        }
        children();
    }
}


// vim: expandtab tabstop=4 shiftwidth=4 softtabstop=4 nowrap

module bspp_threaded_rod(
    size, l, h, 
    left_handed=false, starts=1,
    bevel,bevel1,bevel2,
    internal=false,
    length, height,
    blunt_start, blunt_start1, blunt_start2,
    lead_in, lead_in1, lead_in2,
    lead_in_ang, lead_in_ang1, lead_in_ang2,
    end_len, end_len1, end_len2,
    lead_in_shape="default",
    anchor, spin, orient, undersize=0
)
{
    assert(is_finite(undersize), "\nundersize must be a finite number.");
    assert(!is_undef(size), "\nUndefined size.");
    assert(is_num(size), "\nsize is not a number.");
    _pitch = 0;
    _diameter = 1;
    index = search(size, bspp_dimensions);
    forcefuncall = assert(len(index), str("\nUnsupported BSPP size ", size, "."));
    p = INCH / bspp_dimensions[index[0]][1][_pitch];
    d = INCH * bspp_dimensions[index[0]][1][_diameter] - undersize;
    theta = 55 / 2;
    H = p / (2 * tan(theta));     // : fundamental triangle height
    hh = 2 * H / 3;               // : actual depth of the thread
    e = H * sin(theta) / 6;       // : rounding arc's height
    r = e / (1 - sin(theta));     // : rounding arc's radius
    s = hh - 2 * e;              // : straight flank depth
    c = tan(theta) * (H / 6 + e); // : crest's half width
    pStart = [-c, -e];
    pEnd = [c, -e];
    vStart = [(p / 2 - tan(theta) * (H / 6 + e)), -hh + e];
    vEnd = [p / 2, -hh];
    segments = 4;
    // right valley rounding:
    valley = arc(n = segments, cp = [p / 2, -(hh - r)], points = [vStart, vEnd]);
    //stroke(valley, width = 0.01, color = "cyan");
    // peak rounding:
    peak = arc(n = 2 * segments, cp = [0, -r], points = [pStart, pEnd]);
    //stroke(peak, width = 0.01, color = "cyan");
    profile = scale(1 / p, concat(reverse(xflip(valley)), peak, valley));
    //stroke(profile, width = 0.01, color = "cyan");
    generic_threaded_rod(
            d = d, length = length, height = height, h=h, l=l, 
            pitch = p, profile = profile,
            left_handed=left_handed,
            bevel=bevel,bevel1=bevel1,bevel2=bevel2,
            internal=internal,
            blunt_start=blunt_start, blunt_start1=blunt_start1, blunt_start2=blunt_start2,
            lead_in=lead_in, lead_in1=lead_in1, lead_in2=lead_in2, lead_in_shape=lead_in_shape,
            lead_in_ang=lead_in_ang, lead_in_ang1=lead_in_ang1, lead_in_ang2=lead_in_ang2,
            end_len=end_len, end_len1=end_len1, end_len2=end_len2,
            anchor=anchor,
            spin=spin,starts=starts,
            orient=orient
    )
    children();
}




// Section: Buttress Threading

// Module: buttress_threaded_rod()
// Synopsis: Creates a buttress-threaded rod.
// SynTags: Geom
// Topics: Threading, Screws
// See Also: buttress_threaded_nut()
// Usage:
//   buttress_threaded_rod(d, l|length, pitch, [internal=], ...) [ATTACHMENTS];
// Description:
//   Constructs a simple buttress threaded rod with a 45° angle.  The buttress thread or sawtooth thread has low friction and high loading
//   in one direction at the cost of higher friction and inferior loading in the other direction.  Buttress threads are sometimes used on
//   vises, which are loaded only in one direction.  
// Arguments:
//   d = Outer diameter of threaded rod.
//   l / length / h / height = Length of threaded rod.
//   pitch = Thread spacing.
//   ---
//   left_handed = if true, create left-handed threads.  Default = false
//   starts = Number of lead starts.  Default: 1
//   bevel = Bevel both ends. True selects automatic sizing, a number specifies the size in mm, false disables beveling, and "reverse" reverses an automatic bevel. See {{generic_threaded_rod()}} for sizing. Default: false for blunt start ends, true otherwise
//   bevel1 = Bottom bevel; accepts the same values as bevel and overrides it.
//   bevel2 = Top bevel; accepts the same values as bevel and overrides it.
//   internal = If true, this is a mask for making internal threads.
//   blunt_start = If true apply truncated blunt start threads at both ends.  Default: true
//   blunt_start1 = If true apply truncated blunt start threads bottom end.
//   blunt_start2 = If true apply truncated blunt start threads top end.
//   end_len = Specify the unthreaded length at the end after blunt start threads.  Default: 0
//   end_len1 = Specify unthreaded length at the bottom
//   end_len2 = Specify unthreaded length at the top
//   lead_in = Specify linear length of the lead in section of the threading with blunt start threads
//   lead_in1 = Specify linear length of the lead in section of the threading at the bottom with blunt start threads
//   lead_in2 = Specify linear length of the lead in section of the threading at the top with blunt start threads
//   lead_in_ang = Specify angular length in degrees of the lead in section of the threading with blunt start threads
//   lead_in_ang1 = Specify angular length in degrees of the lead in section of the threading at the bottom with blunt start threads
//   lead_in_ang2 = Specify angular length in degrees of the lead in section of the threading at the top with blunt start threads
//   lead_in_shape = Specify the shape of the thread lead in by giving a text string or function.  Default: "default"
//   teardrop = If true, adds a teardrop profile to the back (Y+) side of the threaded rod, for 3d printability of horizontal holes. If numeric, specifies the proportional extra distance of the teardrop flat top from the screw center, or set to "max" for a pointed teardrop. Default: false
//   d1 = Bottom outside diameter of threads.
//   d2 = Top outside diameter of threads.
//   anchor = Translate so anchor point is at origin (0,0,0).  See [anchor](attachments.scad#subsection-anchor).  Default: `CENTER`
//   spin = Rotate this many degrees around the Z axis after anchor.  See [spin](attachments.scad#subsection-spin). Default: 0
//   orient = Vector to rotate top toward, after spin.  See [orient](attachments.scad#subsection-orient).  Default: `UP`
//   $slop = The printer-specific slop value, which adds clearance (`4*$slop`) to internal threads.
// Example(2D):
//   projection(cut=true)
//       buttress_threaded_rod(d=10, l=15, pitch=2, orient=BACK);
// Examples(Med):
//   buttress_threaded_rod(d=25, l=20, pitch=2, $fa=1, $fs=1,end_len=0);
//   buttress_threaded_rod(d=10, l=20, pitch=1.25, left_handed=true, $fa=1, $fs=1);
// Example(Med;VPR=[100,0,5];VPD=220): Masking a Horizontal Threaded Hole
//   difference() {
//     cuboid(50);
//     buttress_threaded_rod(
//         d=25, l=51, pitch=4, $fn=36,
//         internal=true, bevel=true,
//         blunt_start=false,
//         teardrop=true, orient=FWD
//     );
//   }

module buttress_threaded_nut(
    nutwidth, id, h,
    pitch, shape="hex", left_handed=false,
    bevel,bevel1,bevel2,bevang=30,starts=1,
    ibevel,ibevel1,ibevel2,height,thickness,
    length, l,
    blunt_start, blunt_start1, blunt_start2,
    lead_in, lead_in1, lead_in2,
    lead_in_ang, lead_in_ang1, lead_in_ang2,
    end_len, end_len1, end_len2,
    lead_in_shape="default",
    anchor, spin, orient
) {
    profile = [
        [  -1/2, -0.77],
        [ -7/16, -0.75],
        [  5/16,  0],
        [  7/16,  0],
        [  7/16, -0.75],
        [  1/ 2, -0.77],
    ];
    generic_threaded_nut(
        nutwidth=nutwidth, id=id, h=h,
        pitch=pitch,
        profile=profile,
        shape=shape,
        left_handed=left_handed,starts=starts,
        bevel=bevel,bevel1=bevel1,bevel2=bevel2,bevang=bevang,
        ibevel=ibevel,ibevel1=ibevel1,ibevel2=ibevel2,
        blunt_start=blunt_start, blunt_start1=blunt_start1, blunt_start2=blunt_start2,
        lead_in=lead_in, lead_in1=lead_in1, lead_in2=lead_in2, lead_in_shape=lead_in_shape,
        lead_in_ang=lead_in_ang, lead_in_ang1=lead_in_ang1, lead_in_ang2=lead_in_ang2,
        end_len=end_len, end_len1=end_len1, end_len2=end_len2,
        l=l,length=length,
        anchor=anchor, spin=spin, height=height, thickness=thickness, 
        orient=orient
    ) children();
}



// Section: Square Threading

// Module: square_threaded_rod()
// Synopsis: Creates a square-threaded rod.
// SynTags: Geom
// Topics: Threading, Screws
// See Also: square_threaded_nut()
// Usage:
//   square_threaded_rod(d, l|length, pitch, [internal=], ...) [ATTACHMENTS];
// Description:
//   Constructs a square profile threaded screw rod.  The greatest advantage of square threads is
//   that they have the least friction and a much higher intrinsic efficiency than trapezoidal threads.
//   They produce no radial load on the nut.  However, square threads cannot carry as much load as trapezoidal threads. 
// Arguments:
//   d = Outer diameter of threaded rod.
//   l / length / h / height = Length of threaded rod.
//   pitch = Thread spacing.
//   ---
//   left_handed = if true, create left-handed threads.  Default = false
//   starts = The number of lead starts.  Default = 1
//   bevel = Bevel both ends. True selects automatic sizing, a number specifies the size in mm, false disables beveling, and "reverse" reverses an automatic bevel. See {{generic_threaded_rod()}} for sizing. Default: false for blunt start ends, true otherwise
//   bevel1 = Bottom bevel; accepts the same values as bevel and overrides it.
//   bevel2 = Top bevel; accepts the same values as bevel and overrides it.
//   internal = If true, this is a mask for making internal threads.
//   blunt_start = If true apply truncated blunt start threads at both ends.  Default: true
//   blunt_start1 = If true apply truncated blunt start threads bottom end.
//   blunt_start2 = If true apply truncated blunt start threads top end.
//   end_len = Specify the unthreaded length at the end after blunt start threads.  Default: 0
//   end_len1 = Specify unthreaded length at the bottom
//   end_len2 = Specify unthreaded length at the top
//   lead_in = Specify linear length of the lead in section of the threading with blunt start threads
//   lead_in1 = Specify linear length of the lead in section of the threading at the bottom with blunt start threads
//   lead_in2 = Specify linear length of the lead in section of the threading at the top with blunt start threads
//   lead_in_ang = Specify angular length in degrees of the lead in section of the threading with blunt start threads
//   lead_in_ang1 = Specify angular length in degrees of the lead in section of the threading at the bottom with blunt start threads
//   lead_in_ang2 = Specify angular length in degrees of the lead in section of the threading at the top with blunt start threads
//   lead_in_shape = Specify the shape of the thread lead in by giving a text string or function.  Default: "default"
//   teardrop = If true, adds a teardrop profile to the back (Y+) side of the threaded rod, for 3d printability of horizontal holes. If numeric, specifies the proportional extra distance of the teardrop flat top from the screw center, or set to "max" for a pointed teardrop. Default: false
//   d1 = Bottom outside diameter of threads.
//   d2 = Top outside diameter of threads.
//   anchor = Translate so anchor point is at origin (0,0,0).  See [anchor](attachments.scad#subsection-anchor).  Default: `CENTER`
//   spin = Rotate this many degrees around the Z axis after anchor.  See [spin](attachments.scad#subsection-spin). Default: 0
//   orient = Vector to rotate top toward, after spin.  See [orient](attachments.scad#subsection-orient).  Default: `UP`
//   $slop = The printer-specific slop value, which adds clearance (`4*$slop`) to internal threads.
// Example(2D):
//   projection(cut=true)
//       square_threaded_rod(d=10, l=15, pitch=2, orient=BACK);
// Examples(Med):
//   square_threaded_rod(d=10, l=20, pitch=2, starts=2, $fn=32);
// Example(Med;VPR=[100,0,5];VPD=220): Masking a Horizontal Threaded Hole
//   difference() {
//     cuboid(50);
//     square_threaded_rod(
//         d=25, l=51, pitch=4, $fn=36,
//         internal=true, bevel=true,
//         blunt_start=false,
//         teardrop=true, orient=FWD
//     );
//   }

module garden_hose_female(gasket_seat=5, addl_space=0, wall=5, texture="none", anchor=BOTTOM, spin=0, orient=UP) {
    tpi = 11.5;
    pitch = 1/tpi * INCH;
    thread_depth = 0.649519*pitch;
    nipple_inside_dia = 25/32 * INCH;
    dia_female = (1 + 1/16 + 0.01) * INCH; // 1.0725" in the spec
    coupling_len = 17/32 * INCH + addl_space;
    coupling_thread_len = 3/8 * INCH;
    gasket_space = coupling_len - coupling_thread_len;
    coupling_total_len = coupling_len + gasket_seat;
    total_dia = dia_female + 2*wall;

    attachable(anchor, spin, orient, d=total_dia, l=coupling_total_len) {
        xrot(180) down(coupling_total_len/2) difference() {
            _tex_cyl(total_dia, coupling_total_len, texture, BOTTOM, "garden_hose_female");
            down(0.2) cylinder(coupling_total_len+0.4, d=nipple_inside_dia+1);
            down(0.1)
                garden_hose_threaded_rod(l=coupling_len+0.1, internal=true, end_len1=0.1, end_len2=gasket_space, lead_in_ang1=38, anchor=BOTTOM);
        }
        children();
    }
}


// Module: garden_hose_gasket()
// Synopsis: Creates a North American garden hose washer or gasket
// SynTags: Geom
// Topics: Threading
// See Also: garden_hose_female()
// Usage:
//   garden_hose_gasket([od=], [id=], [thickness=]) [ATTACHMENTS];
// Description:
//   Constructs a garden hose washer that fits inside a female hose coupler compatible with a standard North American garden hose. This would typically be 3D printed using TPU or another waterproof flexible material.
// Arguments:
//   od = Outer diameter, normally 1" converted to millimeters. Default: 25.4
//   id = Inner diameter, normally 5/8" converted to millimeters. Default: 15.875
//   thickness = Normally 1/8" thick, converted to millimeters. Default: 3
//   anchor = Translate so anchor point is at origin (0,0,0). See [anchor](attachments.scad#subsection-anchor).  Default: `BOTTOM`
//   spin = Rotate this many degrees around the Z axis after anchor. See [spin](attachments.scad#subsection-spin).  Default: 0
//   orient = Vector to rotate top toward, after spin. See [orient](attachments.scad#subsection-orient).
// Example:
//   garden_hose_gasket();
// Example(Med;NoAxes;VPD=87;VPR=[110,0,116];VPT=[0,0,10]): Cut-away assembly view of male hose connector (yellow), female hose connector (green), and hose gasket (brown).
//   $fn = 60;
//   color("lightgreen") difference() {
//       garden_hose_female(texture="knurled");
//       down(3) cube(25);
//   }
//   color("brown") up(5) garden_hose_gasket();
//   up(8.01) zrot(60) xrot(180) garden_hose_male(anchor=TOP);

module garden_hose_gasket(od=25.4, id=15.875, thickness=3, anchor=BOTTOM, spin=0, orient=UP) {
    attachable(anchor, spin, orient, d=od, l=thickness) {
        difference() {
            cylinder(thickness, d=od, center=true, $fa=4);
            cylinder(thickness+0.1, d=id, center=true, $fa=4);
        }
        children();
    }
}



// Section: Pipe Threading

// Module: npt_threaded_rod()
// Synopsis: Creates NPT pipe threading.
// SynTags: Geom
// Topics: Threading, Screws
// See Also: acme_threaded_rod()
// Usage:
//   npt_threaded_rod(size, [internal=], [undersize=], [hollow=], ...) [ATTACHMENTS];
// Description:
//   Constructs a standard NPT pipe end threading. If `internal=true`, creates a mask for making
//   internal pipe threads.  Tapers smaller upward if `internal=false`.  Tapers smaller downward
//   if `internal=true`.  If `hollow=true` and `internal=false`, then the pipe threads are
//   hollowed out into a pipe with the apropriate internal diameter.
// Arguments:
//   size = NPT standard pipe size in inches.  1/16", 1/8", 1/4", 3/8", 1/2", 3/4", 1", 1+1/4", 1+1/2", or 2".  Default: 1/2"
//   ---
//   left_handed = If true, create left-handed threads.  Default = false
//   bevel = Bevel both ends. True selects automatic sizing, a number specifies the size in mm, false disables beveling, and "reverse" reverses an automatic bevel. See {{generic_threaded_rod()}} for sizing. Default: false for blunt start ends, true otherwise
//   bevel1 = Bottom bevel; accepts the same values as bevel and overrides it.
//   bevel2 = Top bevel; accepts the same values as bevel and overrides it.
//   hollow = If true, create a pipe with the correct internal diameter.
//   internal = If true, make this a mask for making internal threads. Positive undersize makes the hole smaller; negative values enlarge it. Faceting compensation and $slop are applied afterward. Default: false
//   undersize = Amount to decrease the thread diameters, in mm, without changing pitch or thread depth. Negative values enlarge the thread. Default: 0
//   anchor = Translate so anchor point is at origin (0,0,0).  See [anchor](attachments.scad#subsection-anchor).  Default: `CENTER`
//   spin = Rotate this many degrees around the Z axis after anchor.  See [spin](attachments.scad#subsection-spin). Default: 0
//   orient = Vector to rotate top toward, after spin.  See [orient](attachments.scad#subsection-orient).  Default: `UP`
//   $slop = The printer-specific slop value, which adds clearance (`4*$slop`) to internal threads.
// Example(2D): The straight gray rectangle reveals the tapered threads.  
//   projection(cut=true) npt_threaded_rod(size=1/4, orient=BACK);
//   right(.533*INCH/2) color("gray") rect([2,0.5946*INCH],anchor=LEFT);
// Examples(Med):
//   npt_threaded_rod(size=3/8, $fn=72);
//   npt_threaded_rod(size=1/2, $fn=72, bevel=true);
//   npt_threaded_rod(size=1/2, left_handed=true, $fn=72);
//   npt_threaded_rod(size=3/4, hollow=true, $fn=96);
// Example:
//   diff("remove"){
//      cuboid([40,40,40])
//      tag("remove"){
//        up(.01)position(TOP)
//            npt_threaded_rod(size=3/4, $fn=96, internal=true, $slop=0.1, anchor=TOP);
//        cyl(d=3/4*INCH, l=42, $fn=32);
//      }
//   }

module garden_hose_male(wall=2.13729, anchor=BOTTOM, spin=0, orient=UP, undersize=0) {
    assert(is_finite(undersize), "\nundersize must be a finite number.");
    tpi = 11.5;
    pitch = 1/tpi * INCH;
    thread_depth = 0.649519*pitch;
    dia_male = (1 + 1/16) * INCH - undersize; // 1.0625"
    pilot = 1/8 * INCH;
    nipple_len = 9/16 * INCH;
    thread_inside_dia = dia_male - 2*thread_depth;
    nipple_inside_dia = thread_inside_dia - 2*wall; // defaults to 25/32 * INCH at undersize=0
    assert(is_finite(wall) && wall>0 && nipple_inside_dia>0, "\nwall and undersize leave no positive bore in the male coupler.");

    attachable(anchor, spin, orient, d=dia_male, l=nipple_len) {
        difference() {
            //garden_hose_threaded_rod(l=nipple_len, end_len2=pilot, bevel2=0.2, lead_in_ang2=44, anchor=CENTER);
            trapezoidal_threaded_rod(d=dia_male, l=nipple_len, pitch=pitch, thread_depth=thread_depth, thread_angle=60, end_len2=pilot, bevel2=0.2, lead_in_ang2=44, anchor=CENTER);
            cylinder(nipple_len+0.2, d=nipple_inside_dia, center=true);
        }
        children();
    }
}


/// Internal function: _tex_cyl()
/// Called by garden_hose_female() and bottle cap functions in bottlecaps.scad,
/// to generate a cylinder with an optional knurling texture.
/// All textures expand the diameter due to not reducing the original wall thickness.
/// w = diameter, hh = height, texture=one of 5 choices, anchor=cylinder anchor end, modname=calling module

module generic_threaded_nut(
    nutwidth,
    id,
    h,
    pitch,
    profile,
    shape="hex",
    left_handed=false,
    starts=1,
    bevel,bevel1,bevel2,bevang=30,
    ibevel, ibevel1, ibevel2,
    id1,id2, height, thickness, 
    length, l,
    blunt_start, blunt_start1, blunt_start2,
    lead_in, lead_in1, lead_in2,
    lead_in_ang, lead_in_ang1, lead_in_ang2,
    end_len, end_len1, end_len2,
    lead_in_shape="default",
    anchor, spin, orient
) {

    starts = assert(is_int(starts) && starts>0, "\nstarts must be a positive integer.") starts;
    extra = 0.01;
    id1 = first_defined([id1,id]);
    id2 = first_defined([id2,id]);
    h = one_defined([h,height,thickness,l,length],"h,height,thickness,l,length");
    dummyA = assert(is_num(pitch) && pitch>=0, "\npitch must be a nonnegative number.")
             assert(is_num(h) && h>0, "\nheight/thickness must be a positive number.")
             assert(in_list(shape,["square","hex"]), "\nshape must be \"hex\" or \"square\".")
             assert(all_positive([id1,id2]), "\nInner diameter(s) of nut must be positive number(s).");
    slope = (id2-id1)/h;
    full_id1 = id1-slope*extra/2;
    full_id2 = id2+slope*extra/2;
    ibevel1 = first_defined([ibevel1,ibevel,true]);
    ibevel2 = first_defined([ibevel2,ibevel,true]);
    bevel1 = first_defined([bevel1,bevel,shape=="hex"]);
    bevel2 = first_defined([bevel2,bevel,shape=="hex"]);
    blunt_start1 = first_defined([blunt_start1,blunt_start,true]);
    blunt_start2 = first_defined([blunt_start2,blunt_start,true]);
    assert(is_bool(blunt_start1) && is_bool(blunt_start2), "\nblunt_start must be boolean.");
    assert(is_finite(nutwidth) && nutwidth>0, "\nnutwidth must be positive.");
    assert(is_finite(bevang) && bevang>0 && bevang<90, "\nbevang must be between 0 and 90 degrees.");
    assert(pitch==0 || is_path(profile,2), "\nProfile must be a 2D path.");
    profmin = pitch==0 ? 0 : pitch*min(column(profile,1));
    pmax = pitch==0 ? 0 : pitch*max(column(profile,1));
    depth = pmax-profmin;
    sides = quantup(segs(max(full_id1,full_id2)/2),starts);
    rsc = pitch==0 ? 1 : 1/cos(180/sides);
    // Use the same circumscribed radii as the actual subtraction mask.
    mask_r = [full_id1,full_id2]*rsc/2 + repeat(2*get_slop(),2);
    face_r = [id1,id2]*rsc/2 + repeat(2*get_slop(),2);
    major_r = [for(i=[0:1]) max(mask_r[i],face_r[i])+pmax];
    outer_r = _nut_end_radii(nutwidth,h,shape,bevel1,bevel2,bevang);
    wall = outer_r-major_r;
    assert(min(wall)>0, "\nNut hole exceeds the available outside dimensions at an end face.");
    // A taper can enlarge an end's cutting cone. Bound that enlargement too.
    taper = abs(mask_r[1]-mask_r[0])/(h+extra);
    ib1 = _nut_ibevel_size(ibevel1,blunt_start1,pitch,depth,h,id1,wall[0],taper);
    ib2 = _nut_ibevel_size(ibevel2,blunt_start2,pitch,depth,h,id2,wall[1],taper);
    assert(abs(ib1)+abs(ib2)<h, "\nCombined internal bevel size exceeds nut thickness.");
    // Explicit bevels may use more than the automatic half-wall allowance,
    // but must still leave material. Negative (reverse) bevels do not flare.
    assert(ib1<=0 || _nut_bevel_flare(ib1,blunt_start1,pitch,depth,taper)<wall[0],
           "\nibevel1 is too large for the nut wall.");
    assert(ib2<=0 || _nut_bevel_flare(ib2,blunt_start2,pitch,depth,taper)<wall[1],
           "\nibevel2 is too large for the nut wall.");
    vnf = linear_sweep(hexagon(id=nutwidth), height=h, center=true);
    attachable(anchor,spin,orient, size=shape=="square" ? [nutwidth,nutwidth,h] : undef, vnf=shape=="hex" ? vnf : undef) {
        difference() {
            _nutshape(nutwidth,h, shape,bevel1,bevel2,bevang=bevang);
            if (pitch==0) 
               cyl(l=h+extra, d1=full_id1+4*get_slop(), d2=full_id2+4*get_slop(),
                   chamfer1=-ib1, chamfer2=-ib2);
            else
               generic_threaded_rod(
                     d1=full_id1,d2=full_id2,
                     l=h+extra,
                     pitch=pitch,
                     profile=profile,
                     left_handed=left_handed,
                     starts=starts,
                     internal=true,
                     bevel1=ib1,bevel2=ib2,
                     blunt_start=blunt_start, blunt_start1=blunt_start1, blunt_start2=blunt_start2,
                     lead_in=lead_in, lead_in1=lead_in1, lead_in2=lead_in2, lead_in_shape=lead_in_shape,
                     lead_in_ang=lead_in_ang, lead_in_ang1=lead_in_ang1, lead_in_ang2=lead_in_ang2,
                     end_len=end_len, end_len1=end_len1, end_len2=end_len2
                );
        }
        children();
    }
}


/// Exterior nut bevels use the radial inset of the circumscribed cutting cylinder.

module generic_threaded_rod(
    d, l, pitch, profile,
    left_handed=false, internal=false,
    bevel, bevel1, bevel2, 
    starts=1,
    d1, d2, length, h, height,
    blunt_start, blunt_start1, blunt_start2,
    lead_in, lead_in1, lead_in2,
    lead_in_ang, lead_in_ang1, lead_in_ang2,
    end_len, end_len1, end_len2,
    lead_in_shape="default",
    teardrop=false,
    anchor, spin, orient
) {
    starts = assert(is_int(starts) && starts>0, "\nstarts must be a positive integer.") starts;
    len = one_defined([l,length,h,height],"l,length,h,height");
    bevel1 = first_defined([bevel1,bevel]);
    bevel2 = first_defined([bevel2,bevel]);
    blunt_start1 = first_defined([blunt_start1, blunt_start, true]);
    blunt_start2 = first_defined([blunt_start2, blunt_start, true]);                           
    r1 = get_radius(d1=d1, d=d);
    r2 = get_radius(d1=d2, d=d);
    lead_in1 = first_defined([lead_in1, lead_in]);
    lead_in2 = first_defined([lead_in2, lead_in]);
    lead_in_func = is_func(lead_in_shape) ? lead_in_shape
                 : assert(is_string(lead_in_shape),"\nlead_in_shape must be a function or string.")
                   let(ind = search([lead_in_shape], _lead_in_table,0)[0])
                   assert(ind!=[],str("\nUnknown lead_in_shape, \"",lead_in_shape,"\"."))
                   _lead_in_table[ind[0]][1];
    dummy0 = 
      assert(all_positive([pitch]),"\nThread pitch must be a positive value.")
      assert(all_positive([len]),"\nLength must be a postive value.")
      assert(is_path(profile,2),"\nProfile must be a 2D path.")
      assert(is_bool(blunt_start1), "\nblunt_start1/blunt_start must be boolean.")
      assert(is_bool(blunt_start2), "\nblunt_start2/blunt_start must be boolean.")
      assert(is_bool(left_handed))
      assert(all_positive([r1,r2]), "\nMust give d or both d1 and d2 as positive values.")
      assert(is_undef(bevel1) || is_finite(bevel1) || is_bool(bevel1) || bevel1=="reverse", "\nbevel1/bevel must be a number, boolean or \"reverse\".")
      assert(is_undef(bevel2) || is_finite(bevel2) || is_bool(bevel2) || bevel2=="reverse", "\nbevel2/bevel must be a number, boolean or \"reverse\".");

    sides = quantup(segs(max(r1,r2)), starts);
    rsc = internal? (1/cos(180/sides)) : 1;    // Internal radius adjusted for faceting
    islop = internal? 2*get_slop() : 0;
    r1adj = r1 * rsc + islop;
    r2adj = r2 * rsc + islop;
    profbounds = pointlist_bounds(profile);
    dummy4 = assert(profbounds[0].x>=-1/2 && profbounds[1].x<=1/2,
                    "\nprofile's x values must lie in the interval [-1/2,1/2].")
             assert(profile[0].x<last(profile).x, "\nprofile's first point must have smaller x value than its last point.");
    extreme = internal? profbounds[1].y : profbounds[0].y;
    profile = !internal ? profile
            : let(
                 maxidx = [for(i=idx(profile)) if (approx(profile[i].y,extreme)) i],
                 cutpt = len(maxidx)==1 ? profile[maxidx[0]].x
                       : mean([profile[maxidx[0]].x, profile[maxidx[1]].x])
              )
              [
                 for(entry=profile) if (entry.x>=cutpt) [entry.x-cutpt-1/2,entry.y], 
                 for(entry=profile) if (entry.x<cutpt) [entry.x-cutpt+1/2,entry.y]
              ];
    profmin = pitch * profbounds[0].y;
    pmax = pitch * profbounds[1].y;
    rmax = max(r1adj,r2adj)+pmax;

    // A positive signed result cuts inward; a negative result flares outward.
    depth = pmax-profmin;
    bev1 = _thread_bevel_size(bevel1, blunt_start1, internal, depth, len, r1adj+profmin);
    bev2 = _thread_bevel_size(bevel2, blunt_start2, internal, depth, len, r2adj+profmin);
    assert(abs(bev1)+abs(bev2)<len, "\nCombined bevel size exceeds length of screw.");
    // This is the bevel size used for constructing the polyhedron.  The bevel is integrated when blunt start is on, but
    // applied later via difference/union if blunt start is off, so set bevel to zero in the latter case.  
    bevel_size1 = blunt_start1?bev1:0;
    bevel_size2 = blunt_start2?bev2:0;
    // This is the bevel size for clipping, which is done only when blunt start is off
    clip_bev1 = blunt_start1?0:bev1;
    clip_bev2 = blunt_start2?0:bev2;
    end_len1_base = !blunt_start1? 0 : first_defined([end_len1,end_len, 0]);
    end_len2_base = !blunt_start2? 0 : first_defined([end_len2,end_len, 0]);    
    // Enlarge end lengths to give sufficient room for requested bevel
    end_len1 = abs(bevel_size1)>0 ? max(end_len1_base, abs(bevel_size1)) : end_len1_base;
    end_len2 = abs(bevel_size2)>0 ? max(end_len2_base, abs(bevel_size2)) : end_len2_base;
    // length to create below/above z=0, with an extra revolution in non-blunt-start case so
    // the threads can continue to the specified length and we can clip off the blunt start                       
    len1 = -len/2 - (blunt_start1?0:pitch);   
    len2 =  len/2 + (blunt_start2?0:pitch);

    // Thread turns below and above z=0, with extra to ensure we go beyond the length needed
    turns1 = len1/pitch-1;
    turns2 = len2/pitch+1;
    dir = left_handed? -1 : 1;
    dummy2=
        assert(abs(bevel_size1)+abs(bevel_size2)<len, "\nCombined bevel size exceeds length of screw.")
        assert(r1adj+extreme*pitch-bevel_size1>0, "\nbevel1 is too large to fit screw diameter.")
        assert(r2adj+extreme*pitch-bevel_size2>0, "\nbevel2 is too large to fit screw diameter.");

    margin1 = profile[0].y==extreme ? profile[0].x : -1/2;
    margin2 = last(profile).y==extreme? last(profile).x : 1/2;
    lead_in_default = pmax-profmin;//2*pitch;
        // 0*360/10;// /4/32*360; higlen_default;//0*4/32*360; //2/32*360;//360*max(pitch/2, pmax-depth)/(2*PI*r2adj);
    // lead_in length needs to be quantized to match the samples
    lead_in_ang1 = !blunt_start1? 0 :
         let(
             user_ang = first_defined([lead_in_ang1,lead_in_ang])
         )
         assert(is_undef(user_ang) || is_undef(lead_in1), "\nCannot define lead_in/lead_in1 by both length and angle.")
         quantup(
                 is_def(user_ang) ? user_ang : default(lead_in1, lead_in_default)*360/(2*PI*r1adj)
                 , 360/sides);
    lead_in_ang2 = !blunt_start2? 0 :
         let(
             user_ang = first_defined([lead_in_ang2,lead_in_ang])
         )
         assert(is_undef(user_ang) || is_undef(lead_in2), "\nCannot define lead_in/lead_in2 by both length and angle.")
         quantup(
                 is_def(user_ang) ? user_ang : default(lead_in2, lead_in_default)*360/(2*PI*r2adj)
                 , 360/sides);
    // cut_ang also need to be quantized, but the comparison is offset by 36*turns1/starts, so we need to pull that factor out
    // of the quantization.  (The loop over angle starts at 360*turns1/starts, not at a multiple of 360/sides.)  
//    cut_ang1 = 360 * (len1/pitch-margin1+end_len1/pitch) / starts + lead_in_ang1;
//    cut_ang2 = 360 * (len2/pitch-margin2-end_len2/pitch) / starts - lead_in_ang2;
    cut_ang1 = quantup(360 * (len1/pitch-margin1+end_len1/pitch) / starts + lead_in_ang1-360*turns1/starts,360/sides)+360*turns1/starts;
    cut_ang2 = quantdn(360 * (len2/pitch-margin2-end_len2/pitch) / starts - lead_in_ang2-360*turns1/starts,360/sides)+360*turns1/starts;
    dummy1 =
      assert(cut_ang1<cut_ang2, "\nlead in lengths are too long for the amount of thread: they overlap.")
      assert(is_num(lead_in_ang1), "\nlead_in1/lead_in must be a number.")
      assert(r1adj+profmin>0 && r2adj+profmin>0, "\nScrew profile deeper than rod radius.");
    map_threads = right((r1adj + r2adj) / 2)                   // Shift profile out to thread radius
                * affine3d_skew(sxz=(r2adj-r1adj)/len)         // Skew correction for tapered threads
                * frame_map(x=[0,0,1], y=[1,0,0])          // Map profile to 3d, parallel to z axis
                * scale(pitch);                            // scale profile by pitch
    start_steps = sides / starts;

    // This is the location for clipping the polyhedron, below the bevel, if one is present, or at length otherwise
    // Clipping is done before scaling to pitch, so we need to divide by the pitch
    rod_clip1 = (len1+abs(bevel_size1))/pitch;
    rod_clip2 = (len2-abs(bevel_size2))/pitch;
    prof3d=path3d(profile,1);
    thread_verts = [
        // Outer loop constructs a vertical column of the screw at each angle
        // covering 360/starts degrees of the cylinder.  
        for (step = [0:1:start_steps])
            let(
                ang = 360 * step/sides,
                dz = step / start_steps,    // z offset for threads at this angle
                rot_prof = zrot(ang*dir)*map_threads,   // Rotate profile to correct angular location
                full_profile =  [   // profile for the entire rod
                    for (turns = [turns1:1:turns2]) 
                        let(
                            tang = turns/starts * 360 + ang,
                            // _EPSILON offset prevents funny looking extensions of the thread from its tip
                            // by forcing values near the tip to evaluate as less than zero = beyond the tip end
                            hsc = tang < cut_ang1 ? lead_in_func(-_EPSILON+1-(cut_ang1-tang)/lead_in_ang1,PI*2*r1adj*lead_in_ang1/360 )
                                : tang > cut_ang2 ? lead_in_func(-_EPSILON+1-(tang-cut_ang2)/lead_in_ang2,PI*2*r2adj*lead_in_ang2/360 )
                                : [1,1],
                            shift_and_scale = [[hsc.x, 0], [0,hsc.y], [dz+turns,(1-hsc.y)*extreme]]
                        )
                        // This is equivalent to apply(right(dz+turns)*higscale, profile)
                        //
                        // The right movement finds the position of the thread along
                        // what will be the z axis after the profile is mapped to 3d,
                        // and higscale creates a taper and the end of the threads.  
                        each prof3d*shift_and_scale
                ],
                // Clip profile at the ends of the rod and add a z coordinate
                full_profile_clipped = [
                    for(pts=full_profile) [max(rod_clip1,min(rod_clip2,pts.x)), pts.y, 0]
                ]
            )
            [
              [0,0,len1],
              //if (true) apply(rot_prof, [len1/pitch,extreme+2/pitch ,0]), 
              if (bevel_size1) apply(rot_prof, [len1/pitch,extreme-bevel_size1/pitch ,0]), 
              each apply(rot_prof, full_profile_clipped),
              if (bevel_size2) apply(rot_prof, [len2/pitch,extreme-bevel_size2/pitch ,0]), 
              //if (true) apply(rot_prof, [len2/pitch,extreme+2/pitch ,0]), 
              [0, 0, len2]
            ]
    ];
    style=internal?"concave":"convex";
    thread_vnf = vnf_join([
                           for (i=[0:1:starts-1])
                             zrot(i*360/starts, p=vnf_vertex_array(thread_verts, reverse=left_handed, style=style,col_wrap=false)),
                          ]);
    slope = (r1adj-r2adj)/len;
    dummy3 = 
      assert(r1adj+pmax-clip_bev1>0, "\nbevel1 is too large to fit screw diameter.")
      assert(r2adj+pmax-clip_bev2>0, "\nbevel2 is too large to fit screw diameter.")
      assert(abs(clip_bev1)+abs(clip_bev2)<len, "\nCombined bevel size exceeds length of screw.");

    attachable(anchor,spin,orient, r1=r1adj, r2=r2adj, l=len) {
        union(){
          difference() {
              vnf_polyhedron(thread_vnf,convexity=10);
              __rot_if_old(){    // works around change in rotate_extrude starting point
                  if (clip_bev1>0)
                      rotate_extrude(angle=360)
                          polygon([[                         0,-len/2],
                                   [r1adj+pmax-clip_bev1      ,-len/2],
                                   [r1adj+pmax-slope*clip_bev1,-len/2+clip_bev1],
                                   [                    rmax+1,-len/2+clip_bev1],
                                   [                    rmax+1, len1-1],
                                   [                         0, len1-1]]);
                  if (clip_bev2>0)
                      rotate_extrude(angle=360)
                          polygon([[                         0, len/2],
                                   [r2adj+pmax-clip_bev2      , len/2],
                                   [r2adj+pmax+slope*clip_bev2, len/2-clip_bev2],
                                   [                    rmax+1, len/2-clip_bev2],
                                   [                    rmax+1, len2+1],
                                   [                         0, len2+1]]);
              }
              if (!blunt_start1 && clip_bev1<=0)
                  down(len/2) cuboid([2*rmax+1,2*rmax+1, -len1+1], anchor=TOP);                     
              if (!blunt_start2 && clip_bev2<=0)
                  up(len/2) cuboid([2*rmax+1,2*rmax+1, len2+1], anchor=BOTTOM);
          }

          // Add bevel for internal thread mask
          if (clip_bev1<0) 
              down(len/2+.001)cyl(l=-clip_bev1, r2=r1adj+profmin, r1=r1adj+profmin+slope*clip_bev1-clip_bev1,anchor=BOTTOM);
          if (clip_bev2<0) 
              up(len/2+.001)cyl(l=-clip_bev2, r1=r2adj+profmin, r2=r2adj+profmin+slope*clip_bev2-clip_bev2,anchor=TOP);

          // Add teardrop profile
          if (teardrop!=false) {
              fact = is_num(teardrop) ? assert(teardrop>=0,"\nteardrop value cannot be negative.")1-1/sqrt(2)+teardrop
                   : is_bool(teardrop) ? 1-1/sqrt(2)+0.05
                   : teardrop=="max" ? 1/sqrt(2)
                   : assert(false,"\ninvalid teardrop value.");
              dummy = assert(fact<=1/sqrt(2), "\nteardrop value too large.");
              pdepth = pmax-profmin;              
              trap1 = back((r1adj+pmax)/sqrt(2),path3d(list_rotate(trapezoid(ang=45,w1 = (r1adj+pmax)*sqrt(2), h = (r1adj+pmax)*fact,anchor=FWD),1),-len/2));
              trap2 = back((r2adj+pmax)/sqrt(2),path3d(list_rotate(trapezoid(ang=45,w1 = (r2adj+pmax)*sqrt(2), h = (r2adj+pmax)*fact,anchor=FWD),1), len/2));
              yproj = [[1,0,0],[0,0,0],[0,0,1]];
              p1a=trap1[0]+unit([0,0,-len/2]-trap1[0])*pdepth*3/4;
              p1b=last(trap1)+unit([0,0,-len/2]-last(trap1))*pdepth*3/4;
              p2a=trap2[0]+unit([0,0,len/2]-trap2[0])*pdepth*3/4;
              p2b=last(trap2)+  unit([0,0,len/2]-last(trap2))*pdepth*3/4     ;
              cut1 = reverse([p1a, p1a*yproj, p1b*yproj, p1b]);
              cut2 = reverse([p2a, p2a*yproj, p2b*yproj, p2b]);
              vert = [
                      [each cut1, each trap1],
                      [each cut2, each trap2]
              ];
              vnf_polyhedron(vnf_vertex_array(vert,caps=true,col_wrap=true));
              //     Old code creates an internal teardrop that unfortunately doesn't print well
              //ang = min(45,opp_hyp_to_ang(rmax+profmin, rmax+pmax));
              //xrot(-90) teardrop(l=l, r1=r1adj+profmin, r2=r2adj+profmin, ang=ang, cap_h1=r1adj+pmax, cap_h2=r2adj+pmax);
          }
        }
        children();
    }
}

module npt_threaded_rod(
    size=1/2,
    left_handed=false,
    bevel,bevel1,bevel2,
    hollow=false,
    internal=false,
    anchor, spin, orient, undersize=0
) {
    assert(is_finite(undersize), "\nundersize must be a finite number.");
    assert(is_finite(size));
    assert(is_bool(left_handed));
    assert(is_undef(bevel) || is_bool(bevel) || is_finite(bevel) || bevel=="reverse",
           "\nbevel must be a number, boolean or \"reverse\".");
    assert(is_bool(hollow));
    assert(is_bool(internal));
    assert(!(internal&&hollow), "\nCannot created a hollow internal threads mask.");
    info_table = [
        // Size    len      OD    TPI
        [ 1/16,  [ 0.3896, 0.308, 27  ]],
        [ 1/8,   [ 0.3924, 0.401, 27  ]],
        [ 1/4,   [ 0.5946, 0.533, 18  ]],
        [ 3/8,   [ 0.6006, 0.668, 18  ]],
        [ 1/2,   [ 0.7815, 0.832, 14  ]],
        [ 3/4,   [ 0.7935, 1.043, 14  ]],
        [ 1,     [ 0.9845, 1.305, 11.5]],
        [ 1+1/4, [ 1.0085, 1.649, 11.5]],
        [ 1+1/2, [ 1.0252, 1.888, 11.5]],
        [ 2,     [ 1.0582, 2.362, 11.5]],
    ];
    info = [for (data=info_table) if(approx(size,data[0])) data[1]][0];
    dummy1 = assert(is_def(info), "\nUnsupported NPT size. Try one of 1/16, 1/8, 1/4, 3/8, 1/2, 3/4, 1, 1+1/4, 1+1/2, 2.");
    l = INCH * info[0];
    d = INCH * info[1] - undersize;
    pitch = INCH / info[2];
    rr = d/2;
    rr2 = rr - l/32;
    r1 = internal? rr2 : rr;
    r2 = internal? rr : rr2;
    depth = pitch * cos(30) * 5/8;
    profile = internal? [
        [-6/16, -depth/pitch],
        [-1/16,  0],
        [-1/32,  0.02],
        [ 1/32,  0.02],
        [ 1/16,  0],
        [ 6/16, -depth/pitch]
    ] : [
        [-7/16, -depth/pitch*1.07],
        [-6/16, -depth/pitch],
        [-1/16,  0],
        [ 1/16,  0],
        [ 6/16, -depth/pitch],
        [ 7/16, -depth/pitch*1.07]
    ];
    assert(!hollow || min(r1,r2)+pitch*min(column(profile,1))>size*INCH/2,
           "\nundersize leaves no wall around the NPT bore.");
    attachable(anchor,spin,orient, l=l, r1=r1, r2=r2) {
        difference() {
            generic_threaded_rod(
                d1=2*r1, d2=2*r2, l=l,
                pitch=pitch,
                profile=profile,
                left_handed=left_handed,
                bevel=bevel,bevel1=bevel1,bevel2=bevel2,
                internal=internal,
                blunt_start=true
            );
            if (hollow) cylinder(h=l+1, d=size*INCH, center=true);
        }
        children();
    }
}



// Module: bspp_threaded_rod()
// Synopsis: Creates British Standard Parallel Pipe (BSPP) threading.
// SynTags: Geom
// Topics: Threading, Screws
// See Also: npt_threaded_rod()
// Usage:
//   bspp_threaded_rod(size, l|length=|h=|height=, [internal=], [undersize=], ...) [ATTACHMENTS];
// Description:
//   British Standard Pipe (BSP) is a set of screw thread standards used internationally (except in the USA)
//   for connecting pipes.  This module implements British STandard Pipe Parallel (BSPP) thread, where the
//   threads are paralell, rather than tapered, and the joint is achieved by compression of an O-ring seal or washer.   
//   Constructs a BSPP end threading. If `internal=true`, creates a mask for making internal pipe threads.
//   .
//   The size was originally based on the inner diameter (in inches) of the pipe, but contemporary pipes have
//   thinner walls, and hence an inner diameter larger than the nominal size.  
// Arguments:
//   size = BSP standard pipe size.  1/16, 1/8, 1/4, 3/8, 1/2, 5/8, 3/4, 7/8, 1, 1+1/8, 1+1/4, 1+3/8, 1+1/2, 1+5/8, 1+3/4, 1+7/8 or 2.
//   l / length / h / height = Length of threaded rod.
//   ---
//   left_handed = If true, create left-handed threads.  Default: false
//   starts = The number of lead starts, a positive integer. Default: 1
//   internal = If true, make this a mask for making internal threads. Positive undersize makes the hole smaller; negative values enlarge it. Faceting compensation and $slop are applied afterward. Default: false
//   bevel = Bevel both ends. True selects automatic sizing, a number specifies the size in mm, false disables beveling, and "reverse" reverses an automatic bevel. See {{generic_threaded_rod()}} for sizing. Default: false for blunt start ends, true otherwise
//   bevel1 = Bottom bevel; accepts the same values as bevel and overrides it.
//   bevel2 = Top bevel; accepts the same values as bevel and overrides it.
//   blunt_start = If true apply truncated blunt start threads at both ends.  Default: true
//   blunt_start1 = If true apply truncated blunt start threads bottom end.
//   blunt_start2 = If true apply truncated blunt start threads top end.
//   end_len = Specify the unthreaded length at the end after blunt start threads.  Default: 0
//   end_len1 = Specify unthreaded length at the bottom
//   end_len2 = Specify unthreaded length at the top
//   lead_in = Specify linear length of the lead in section of the threading with blunt start threads
//   lead_in1 = Specify linear length of the lead in section of the threading at the bottom with blunt start threads
//   lead_in2 = Specify linear length of the lead in section of the threading at the top with blunt start threads
//   lead_in_ang = Specify angular length in degrees of the lead in section of the threading with blunt start threads
//   lead_in_ang1 = Specify angular length in degrees of the lead in section of the threading at the bottom with blunt start threads
//   lead_in_ang2 = Specify angular length in degrees of the lead in section of the threading at the top with blunt start threads
//   lead_in_shape = Specify the shape of the thread lead in by giving a text string or function.  Default: "default"
//   undersize = Amount to decrease the thread diameters, in mm, without changing pitch or thread depth. Negative values enlarge the thread. Default: 0
//   anchor = Translate so anchor point is at origin (0,0,0).  See [anchor](attachments.scad#subsection-anchor).  Default: `CENTER`
//   spin = Rotate this many degrees around the Z axis after anchor.  See [spin](attachments.scad#subsection-spin). Default: 0
//   orient = Vector to rotate top toward, after spin.  See [orient](attachments.scad#subsection-orient).  Default: `UP`
//   $slop = The printer-specific slop value, which adds clearance (`4*$slop`) to internal threads.
// Examples(Med):
//   bspp_threaded_rod(size=3/8, length = 10, $fn=72);
//   bspp_threaded_rod(size=1/2, length = 10, $fn=72, bevel=true);
//   bspp_threaded_rod(size=1/2, length = 10, left_handed=true, $fn=72);
//   bspp_threaded_rod(size=3/4, length = 10, internal=true, $fn=96);
// Example:
//   diff("remove"){
//      cuboid([30,30,30])
//      tag("remove"){
//        up(.01)position(TOP)
//            bspp_threaded_rod(size=1/2, length=30, $fn=96, internal=true, $slop=0.1, anchor=TOP);
//        cyl(d=3/4*INCH, l=42, $fn=32);
//     }
//   }

bspp_dimensions = [
        // Size  TPI   OD
        [ 1/16,  [ 28, 0.3041 ]],
        [ 1/8,   [ 28, 0.3830 ]],
        [ 1/4,   [ 19, 0.5180 ]],
        [ 3/8,   [ 19, 0.6560 ]],
        [ 1/2,   [ 14, 0.8250 ]],
        [ 5/8,   [ 14, 0.9020 ]],
        [ 3/4,   [ 14, 1.0410 ]],
        [ 7/8,   [ 14, 1.1890 ]],
        [ 1,     [ 11, 1.3090 ]],
        [ 1+1/8, [ 11, 1.4920 ]],
        [ 1+1/4, [ 11, 1.6500 ]],
        [ 1+3/8, [ 11, 1.7450 ]],
        [ 1+1/2, [ 11, 1.8820 ]],
        [ 1+5/8, [ 11, 2.0820 ]],
        [ 1+3/4, [ 11, 2.1160 ]],
        [ 1+7/8, [ 11, 2.2440 ]],
        [ 2,     [ 11, 2.3470 ]],
        ];

module thread_helix(
    d, pitch, thread_depth, flank_angle, turns,
    profile, starts=1, left_handed=false, internal=false,
    d1, d2, thread_angle, 
    lead_in_shape,
    lead_in, lead_in1, lead_in2,
    lead_in_ang, lead_in_ang1, lead_in_ang2,
    lead_in_sample=10,
    anchor, spin, orient
) {
    starts = assert(is_int(starts) && starts>0, "\nstarts must be a positive integer.") starts;
    dummy1=assert(num_defined([thread_angle,flank_angle])<=1, "\nCannot define both flank angle and thread angle.")
           assert(is_undef(profile) || !any_defined([thread_depth, flank_angle, thread_angle]),
                  "\nCannot give thread_depth, flank_angle or thread_angle with a profile.")
           assert(all_positive([turns]), "\nThe turns parameter must be a positive number.")
           assert(all_positive(pitch), "\npitch must be a positive number.")
           assert(num_defined([flank_angle,thread_angle])<=1, "\nCannot give both thread_angle and flank_angle.")
           assert(is_def(profile) || is_def(thread_depth), "\nIf profile is not given, must give thread depth.");
    flank_angle = first_defined([flank_angle,u_mul(0.5,thread_angle),15]);
    h = pitch*starts*abs(turns);
    r1 = get_radius(d1=d1, d=d);
    r2 = get_radius(d1=d2, d=d);
    assert(all_positive([r1,r2]), "\nMust give d or both d1 and d2 as positive values.");
    profile = is_def(profile) ? profile :
        let(
            tdp = thread_depth / pitch,
            dz = tdp * tan(flank_angle),
            cap = (1 - 2*dz)/2
        )
        assert(cap/2+dz<=0.5, "\nInvalid geometry: incompatible thread depth and thread_angle/flank_angle.")
        internal?
          [
            [-cap/2-dz, tdp],
            [-cap/2,    0  ],
            [+cap/2,    0  ],
            [+cap/2+dz, tdp],
          ]
        :
          [
            [+cap/2+dz, 0  ],
            [+cap/2,    tdp],
            [-cap/2,    tdp],
            [-cap/2-dz, 0  ],
          ];

    pline = mirror([-1,1],  p = profile * pitch);
    dir = left_handed? -1 : 1;
    attachable(anchor,spin,orient, r1=r1, r2=r2, l=h) {
        union(){
        zrot_copies(n=starts)
            spiral_sweep(pline, h=h, r1=r1, r2=r2, turns=turns*dir, internal=internal,
                         lead_in_shape=lead_in_shape,
                         lead_in=lead_in, lead_in1=lead_in1, lead_in2=lead_in2,
                         lead_in_ang=lead_in_ang, lead_in_ang1=lead_in_ang1, lead_in_ang2=lead_in_ang2,
                         lead_in_sample=lead_in_sample,anchor=CENTER);
        }
        children();
    }
}



